local config = {
  ui_story_5085_50850100_1_dialog_content = "Ugh, minha cabeça...",
  ui_story_5085_50850100_2_dialog_content = "Parece que... Eu engoli um monte de água do mar...",
  ui_story_5085_50850100_3_dialog_content = "<color=#e8d9bb>Fwoosh, Fwoosh—</color>",
  ui_story_5085_50850100_4_dialog_content = "Ugh, estou tão cansado do som das ondas... Espera, eu realmente estou na praia?",
  ui_story_5085_50850100_5_dialog_content = "Ah... Você finalmente acordou? Como está se sentindo?",
  ui_story_5085_50850100_6_dialog_content = "Vice...?",
  ui_story_5085_50850100_7_dialog_content = "O sol está tão brilhante... Onde estamos?",
  ui_story_5085_50850100_8_dialog_content = "Ah! Você está acordado!",
  ui_story_5085_50850100_10_dialog_content = "Huh...? V-Você não é Vice!",
  ui_story_5085_50850100_11_dialog_content = "Desculpe, pensei que você fosse outra pessoa! Não, espera... Eu deveria estar agradecendo a você por salvar minha vida...",
  ui_story_5085_50850100_12_dialog_content = "Acalme-se, eu estava apenas fazendo o que pude para ajudar.",
  ui_story_5085_50850100_13_dialog_content = "Você é a primeira pessoa que conheci neste <color=#FFB400>novo mundo</color>, sabe!",
  ui_story_5085_50850100_14_dialog_content = "Julgando pela sua situação, não parece que estamos no mundo do Oren mais. Isso pode ser um problema...",
  ui_story_5085_50850100_15_dialog_content = "O que é o Oren? Espere... Você disse \"novo mundo\"?!",
  ui_story_5085_50850100_16_dialog_content = "Isso mesmo!",
  ui_story_5085_50850100_17_dialog_content = "Meus amigos e eu estávamos pesquisando maneiras de viajar para o Submundo...",
  ui_story_5085_50850100_18_dialog_content = "Mas então algo deu errado com o portal, e acabamos aqui dentro!",
  ui_story_5085_50850100_19_dialog_content = "Mesmo com toda a minha experiência em aventuras, não faço ideia de como prosseguir! Então, amigo—",
  ui_story_5085_50850100_20_dialog_content = "Você se importaria em me apresentar este mundo?",
  ui_story_5085_50850100_21_dialog_content = "Apresentar... o mundo...?",
  ui_story_5085_50850100_22_dialog_content = "<color=#e8d9bb>Cau—Cau—</color>",
  ui_story_5085_50850100_23_dialog_content = "... E essa é mais ou menos a história do Astra.",
  ui_story_5085_50850100_24_dialog_content = "Mas eu não acho que estamos no continente principal anymore. Se for o caso, isso parece uma ilha fora da costa de Astra.",
  ui_story_5085_50850100_25_dialog_content = "PlayerName! A União Mensageira acabou de nos enviar as últimas notícias sobre algumas ruínas que encontraram em uma ilha!",
  ui_story_5085_50850100_26_dialog_content = "Oh? Você quer dizer as ruínas da ilha sobre as quais todos têm falado ultimamente?",
  ui_story_5085_50850100_27_dialog_content = "Isso mesmo! Aparentemente, eles pertencem a um antigo reino Auroriano que raramente aparece nos registros históricos.",
  ui_story_5085_50850100_28_dialog_content = "Alguns estudiosos acreditam que este reino pode preencher a lacuna que apareceu depois que os Aurorianos deixaram Northland!",
  ui_story_5085_50850100_29_dialog_content = "Lumopolis e Umbraton já estão se preparando para investigar a ilha, e estão oferecendo comissões massivas para quem ajudar com suas explorações!",
  ui_story_5085_50850100_30_dialog_content = "D-Disse \"comissões enormes\"?!",
  ui_story_5085_50850100_31_dialog_content = "Nós... Não estamos muito atrasados para nos inscrever, estamos?!",
  ui_story_5085_50850100_32_dialog_content = "Heehee, eu sabia que você estaria interessado!",
  ui_story_5085_50850100_33_dialog_content = "E não se preocupe com as despesas de viagem. Eu já conversei com alguns que também estão indo nessa direção.",
  ui_story_5085_50850100_34_dialog_content = "Todos concordaram em se encontrar e ir juntos para reduzir os custos de viagem!",
  ui_story_5085_50850100_35_dialog_content = "Só preciso que você confirme com eles os detalhes da viagem antes de partirmos.",
  ui_story_5085_50850100_36_dialog_content = "Você é muito meticuloso... Tá bem, vou fazer a verificação final agora!",
  ui_story_5085_50850100_37_dialog_content = "PlayerName! Eu quero ir para a ilha e procurar música do antigo reino!",
  ui_story_5085_50850100_38_dialog_content = "Tenho certeza que isso fará minhas performances Rediesel queimarem mais quentes do que nunca! Você só precisa me levar junto!",
  ui_story_5085_50850100_39_dialog_content = "Sem problemas!",
  ui_story_5085_50850100_40_dialog_content = "Há rumores de mechs antigos nas ruínas. Minha curiosidade estava me dominando. Eu tinha que ver por mim mesmo.",
  ui_story_5085_50850100_41_dialog_content = "Por favor, PlayerName!",
  ui_story_5085_50850100_42_dialog_content = "Sem objeções aqui!",
  ui_story_5085_50850100_43_dialog_content = "V-Vamos deixar uma coisa clara! Eu não estou indo porque quero passar algum tempo na praia neste verão...",
  ui_story_5085_50850100_44_dialog_content = "Acabei de ver o quanto Vice estava trabalhando duro para se preparar para esta viagem... Eu não quero que ela exagere nas coisas, então achei que deveria acompanhá-la.",
  ui_story_5085_50850100_45_dialog_content = "Claro, muito apreciado, Zarya!",
  ui_story_5085_50850100_46_dialog_content = "<color=#e8d9bb>Com uma equipe de cinco agora escolhida, a festa parte para uma emocionante aventura na ilha...</color>",
  ui_story_5085_50850100_47_dialog_content = "Todos aqui? Bom! Agora vamos seguir em direção ao nosso destino—",
  ui_story_5085_50850100_48_dialog_content = "Para as ruínas da ilha!",
  ui_story_5085_50850100_49_dialog_content = "Espero que descubramos alguns instrumentos musicais antigos!",
  ui_story_5085_50850100_50_dialog_content = "Ou alguns mechas antigos lendários!",
  ui_story_5085_50850100_51_dialog_content = "Esta ilha certamente guarda muitos mistérios.",
  ui_story_5085_50850100_52_dialog_content = "(Vice e os outros... todos parecem um pouco otimistas demais sobre essa viagem.)",
  ui_story_5085_50850100_53_dialog_content = "(As pessoas geralmente voltam dessas aventuras de mãos vazias... Mas talvez eu esteja sendo muito negativo.)",
  ui_story_5085_50850100_54_dialog_content = "PlayerName, o Sr. Corax está chamando!",
  ui_story_5085_50850100_55_dialog_content = "Ouvi dizer que você está a caminho das ruínas da ilha. Isso é verdade?",
  ui_story_5085_50850100_56_dialog_content = "Eu realmente queria que você se juntasse a mim nesta expedição e procurasse por qualquer conhecimento médico Auroriano perdido, mas parece que eu estava atrasado demais.",
  ui_story_5085_50850100_57_dialog_content = "Até você também?!",
  ui_story_5085_50850100_58_dialog_content = "Desculpe... Muitas pessoas têm perguntado pelos mesmos motivos.",
  ui_story_5085_50850100_59_dialog_content = "Explorar ruínas nunca é um assunto simples. Esperançosamente, a equipe que você montou inclui lutadores e médicos capazes.",
  ui_story_5085_50850100_60_dialog_content = "Pelo que ouvi, o clima extremo por si só já derrotou muitas equipes de exploração. Eu me preocupo por sua causa.",
  ui_story_5085_50850100_61_dialog_content = "Acho que vamos ficar bem...",
  ui_story_5085_50850100_62_dialog_content = "O mar esteve calmo todo esse tempo...",
  ui_story_5085_50850100_63_dialog_content = "O que é isso?! Relâmpago... em um dia claro?!",
  ui_story_5085_50850100_64_dialog_content = "Ahhhh—Está chovendo fogo! Protejam-se, todos!",
  ui_story_5085_50850100_65_dialog_content = "O-O navio não vai virar, vai?!",
  ui_story_5085_50850100_66_dialog_content = "Segurem-se, todos!",
  ui_story_5085_50850100_67_dialog_content = "<size=50><color=#e8d9bb>Estrondo-!</color></size>",
  ui_story_5085_50850100_68_dialog_content = "<color=#e8d9bb>O navio está se despedaçando, e a tripulação está se agarrando desesperadamente aos destroços, jogados pelas ondas impiedosas.</color>",
  ui_story_5085_50850100_69_dialog_content = "<color=#e8d9bb>À deriva nas correntes, me encontrei aqui antes que eu percebesse...</color>",
  ui_story_5085_50850100_70_dialog_content = "Então... Também não estou muito familiarizado com este lugar. Me desculpe.",
  ui_story_5085_50850100_71_dialog_content = "Não tenho certeza se posso te ajudar de alguma forma, também...",
  ui_story_5085_50850100_72_dialog_content = "Eu vejo. Tudo bem!",
  ui_story_5085_50850100_73_dialog_content = "Obrigado pela informação! Agora sinto que tenho uma boa leitura desta situação.",
  ui_story_5085_50850100_74_dialog_content = "Quando se trata de lugares como ilhas e ruínas, eu tenho toneladas de experiência!",
  ui_story_5085_50850100_75_dialog_content = "Que alívio! Antes de virmos para cá, eu tinha uma boa ideia do que esperar.",
  ui_story_5085_50850100_76_dialog_content = "Apenas me perguntando onde os outros acabaram. Eles também devem ter sido levados para a costa, certo?",
  ui_story_5085_50850100_77_dialog_content = "Seus amigos... Ah, isso me lembra!",
  ui_story_5085_50850100_78_dialog_content = "Klaudia e Patty também foram enviados para este mundo, mas não consegui encontrar nenhum deles...",
  ui_story_5085_50850100_79_dialog_content = "Mas algo me diz que eles definitivamente estão nesta ilha!",
  ui_story_5085_50850100_80_dialog_content = "E se você me permite a expressão, parece que você e eu estamos no mesmo barco aqui.",
  ui_story_5085_50850100_81_dialog_content = "Haha, você pode dizer isso de novo...",
  ui_story_5085_50850100_82_dialog_content = "E já que é esse o caso... Por que não tentamos procurar nossos amigos juntos?",
  ui_story_5085_50850100_83_dialog_content = "Seremos muito mais eficazes se trabalharmos em equipe!",
  ui_story_5085_50850100_84_dialog_content = "Sério?! Ah, muito obrigado pela sua ajuda! Sabe, você parece bastante preocupado com seus amigos também. Você continuou chamando \"Vice\" quando estava inconsciente mais cedo...",
  ui_story_5085_50850100_85_dialog_content = "Ela deve ser sua amiga mais próxima, huh?",
  ui_story_5085_50850100_86_dialog_content = "E-É isso que você acha?!",
  ui_story_5085_50850100_87_dialog_content = "... Talvez você esteja certo. Vir aqui foi ideia dela, e eu nem hesitei em me juntar a ela.",
  ui_story_5085_50850100_88_dialog_content = "Ah, entendi! Ela deve amar aventuras. Estou ainda mais animado para conhecê-la agora!",
  ui_story_5085_50850100_89_dialog_content = "Você consegue andar? Você pode se apoiar em mim se estiver machucado.",
  ui_story_5085_50850100_90_dialog_content = "Obrigado, mas acho que posso me virar.",
  ui_story_5085_50850100_91_dialog_content = "Bom! Então, permita-me apresentar-me formalmente—",
  ui_story_5085_50850100_92_dialog_content = "Meu nome é Reisalin Stout, mas você pode simplesmente me chamar de Ryza!",
  ui_story_5085_50850100_93_dialog_content = "Prazer em conhecê-lo, Ryza. Meu nome é PlayerName, mas a maioria das pessoas apenas me chama de Navegador.",
  ui_story_5085_50850100_94_dialog_content = "Parece bom! Ansioso para trabalhar com você, Navegador!",
  ui_story_5085_50850100_95_dialog_content = "Agora vamos indo!",
  ui_story_5085_50850201_1_dialog_content = "Ufa... Isso parece bastante útil.",
  ui_story_5085_50850201_2_dialog_content = "Uau, essa flor é linda! Eu me pergunto se posso usá-la como substituta para as Flores de Saúde.",
  ui_story_5085_50850201_3_dialog_content = "Acha que essa pedra tem alguma utilidade? Eu deveria levá-la comigo, só para garantir...",
  ui_story_5085_50850201_4_dialog_content = "Uh, parece que sua mochila já está bastante cheia.",
  ui_story_5085_50850201_5_dialog_content = "Ah! Você está certo, eu devo ter me empolgado um pouco com a minha coleta...",
  ui_story_5085_50850201_6_dialog_content = "Você parece gostar bastante de plantas, especialmente... raízes de grama?",
  ui_story_5085_50850201_7_dialog_content = "Eheheh... Não exatamente. Eu só quero tentar usar esses como materiais de <color=#FFB400>alquimia</color>!",
  ui_story_5085_50850201_8_dialog_content = "A-Alquimia?!",
  ui_story_5085_50850201_9_dialog_content = "Huh? A alquimia não existe neste mundo ou algo assim?",
  ui_story_5085_50850201_10_dialog_content = "Emmm, no que diz respeito ao mundo, é mais uma arte perdida do passado antigo.",
  ui_story_5085_50850201_11_dialog_content = "Então, isso realmente existe no seu mundo?",
  ui_story_5085_50850201_12_dialog_content = "Isso mesmo! E não me subestime, na verdade sou um <color=#FFB400>alquimista</color> bastante realizado.",
  ui_story_5085_50850201_13_dialog_content = "Posso usar todos os tipos de objetos regulares como materiais e <color=#FFB400>sintetizá-los</color> em medicamentos e outros itens úteis!",
  ui_story_5085_50850201_14_dialog_content = "Sério? Isso é impressionante!",
  ui_story_5085_50850201_15_dialog_content = "Se eu tivesse um grande e bom caldeirão de alquimia... Então eu poderia mostrar a você o que eu realmente posso fazer!",
  ui_story_5085_50850201_16_dialog_content = "Um caldeirão, huh? Não tenho certeza se encontraremos algo assim em uma ilha deserta... Mas talvez as ruínas tenham algo que você possa usar?",
  ui_story_5085_50850201_17_dialog_content = "Em qualquer caso, vamos seguir em frente. Podemos até encontrar coisas melhores à frente.",
  ui_story_5085_50850201_18_dialog_content = "Agora você está falando a minha língua!",
  ui_story_5085_50850201_19_dialog_content = "Deixe-me apenas aliviar um pouco minha carga primeiro.",
  ui_story_5085_50850201_20_dialog_content = "Posso te ajudar a carregar algumas coisas também. Afinal, duvido que vamos deixar esta ilha tão cedo.",
  ui_story_5085_50850201_21_dialog_content = "Se vamos ficar presos aqui por alguns dias, tenho certeza de que sua alquimia definitivamente será útil!",
  ui_story_5085_50850201_22_dialog_content = "Você tem razão!",
  ui_story_5085_50850201_23_dialog_content = "Então começaremos encontrando nossos amigos, depois procuraremos o caldeirão...",
  ui_story_5085_50850201_24_dialog_content = "Graah—",
  ui_story_5085_50850201_25_dialog_content = "Ah! É-É um monstro!",
  ui_story_5085_50850201_26_dialog_content = "Todos os monstros do seu mundo têm essa aparência assustadora?!",
  ui_story_5085_50850201_27_dialog_content = "Existem Eclipsitas até numa ilha remota como esta?!",
  ui_story_5085_50850201_28_dialog_content = "Isso é ruim... sem Aurorianos por perto...",
  ui_story_5085_50850201_29_dialog_content = "Eclipsitas? É isso que você chama essas coisas?",
  ui_story_5085_50850201_30_dialog_content = "Aquele parece que está carregando algo em suas garras...",
  ui_story_5085_50850201_31_dialog_content = "Espere um minuto, isso não é...",
  ui_story_5085_50850201_32_dialog_content = "Vice pacote?!",
  ui_story_5085_50850201_33_dialog_content = "<color=#e8d9bb>Que droga!</color>",
  ui_story_5085_50850201_34_dialog_content = "Você Eclipsita podre! Devolva o meu... Ah! PlayerName!",
  ui_story_5085_50850201_35_dialog_content = "Timing perfeito! Nossos suprimentos ainda estão naquela mochila! Vamos ter problemas se não a pegarmos de volta!",
  ui_story_5085_50850201_36_dialog_content = "Me dê uma mão!",
  ui_story_5085_50850201_37_dialog_content = "Entendido!",
  ui_story_5085_50850202_1_dialog_content = "Ufa, isso cuida disso!",
  ui_story_5085_50850202_2_dialog_content = "Teríamos que sobreviver como homens das cavernas sem esses suprimentos.",
  ui_story_5085_50850202_3_dialog_content = "Estou tão feliz que te encontrei, PlayerName! Mas uh, quem é esse...?",
  ui_story_5085_50850202_4_dialog_content = "Ah, você deve ser Vice! O Navegador me falou sobre você quando nos conhecemos pela primeira vez. Meu nome é Ryza!",
  ui_story_5085_50850202_5_dialog_content = "Eh—Sim, meu nome é Vice; prazer em conhecer você, Senhorita Ryza! Hum... Você também é uma aventureira explorando a ilha?",
  ui_story_5085_50850202_6_dialog_content = "Meio que... Para ser mais específico, ela é uma alquimista que veio de outro mundo.",
  ui_story_5085_50850202_7_dialog_content = "Um alquimista... de outro mundo?",
  ui_story_5085_50850202_8_option_content = "Explique a situação para Vice",
  ui_story_5085_50850202_9_dialog_content = "<color=#e8d9bb>Eu dou a Vice um resumo rápido de como Ryza e eu nos conhecemos.</color>",
  ui_story_5085_50850202_10_dialog_content = "Então foi isso que aconteceu, hein?",
  ui_story_5085_50850202_11_dialog_content = "Sim! Ele continuou chamando seu nome quando ainda estava inconsciente também!",
  ui_story_5085_50850202_12_dialog_content = "Entendo...",
  ui_story_5085_50850202_13_dialog_content = "A-Aham... Acho que devemos passar para algo mais importante, como nossa situação atual.",
  ui_story_5085_50850202_14_dialog_content = "Concordo.",
  ui_story_5085_50850202_15_dialog_content = "Quando eu estava perseguindo aquele Eclipsite, percebi que havia muito mais Eclipsites nesta ilha do que eu pensava.",
  ui_story_5085_50850202_16_dialog_content = "Os recursos também estão especialmente escassos. Se não conseguirmos encontrar uma maneira de reabastecer nossos suprimentos...",
  ui_story_5085_50850202_17_dialog_content = "Só um segundo, Vice! Você está machucado, não está?",
  ui_story_5085_50850202_18_dialog_content = "Se não se importar, tente aplicar um pouco deste remédio na sua ferida. Eu o fiz usando alquimia.",
  ui_story_5085_50850202_19_dialog_content = "Hã? Tudo bem, é só um arranhão... Eu preferiria não desperdiçar sua preciosa medicina com algo assim...",
  ui_story_5085_50850202_20_dialog_content = "Está bem, sério—",
  ui_story_5085_50850202_21_dialog_content = "<color=#e8d9bb>Ryza gentilmente espalhou um pouco de seu remédio na ferida de Vice—</color>",
  ui_story_5085_50850202_22_dialog_content = "Nngh... Hã?!",
  ui_story_5085_50850202_23_dialog_content = "Está completamente curado... Isso é o poder da sua alquimia, Ryza?",
  ui_story_5085_50850202_24_dialog_content = "Você deve ser capaz de fazer qualquer coisa com ele!",
  ui_story_5085_50850202_25_dialog_content = "Isso mesmo! A alquimia pode resolver praticamente qualquer problema! Ou pelo menos eu gosto de pensar assim... Mas tenho certeza de que tornará a vida nesta ilha remota muito mais fácil! Pode até ser útil contra os Eclipsitas!",
  ui_story_5085_50850202_26_dialog_content = "Tenho certeza que pode! Eu acredito na sua força.",
  ui_story_5085_50850202_27_dialog_content = "Aposto que Vice também vê! Você seria o companheiro perfeito para explorar ruínas antigas e territórios secretos.",
  ui_story_5085_50850202_28_dialog_content = "Concordo! Nada é melhor do que cruzar caminhos com um aliado poderoso como você.",
  ui_story_5085_50850202_29_dialog_content = "Haha, acho que é melhor eu trabalhar duro pelo bem de todos também! E vou começar encontrando o caldeirão.",
  ui_story_5085_50850202_30_dialog_content = "Um caldeirão?",
  ui_story_5085_50850202_31_dialog_content = "É o que Ryza precisa para realizar alquimia e criar todos os tipos de itens. Qualquer coisa que se pareça com um pote servirá.",
  ui_story_5085_50850202_32_dialog_content = "Ah, entendi.",
  ui_story_5085_50850202_33_dialog_content = "Vi algo assim no meu caminho para cá. Parecia algum tipo de vaso cerimonial nas ruínas...",
  ui_story_5085_50850202_34_dialog_content = "<color=#e8d9bb>O som de uma flauta surge repentinamente das profundezas da floresta—</color>",
  ui_story_5085_50850202_35_dialog_content = "Acho que tem alguém na floresta!",
  ui_story_5085_50850202_36_dialog_content = "Esse instrumento... Deve ser o Klaudia!",
  ui_story_5085_50850202_37_dialog_content = "Por favor, venha comigo! Ela é minha companheira mais confiável... Assim como minha melhor amiga!",
  ui_story_5085_50850301_1_dialog_content = "Venha, meu amigo de uma terra distante! Vamos derrotar os Eclipsitas em mãos!♪",
  ui_story_5085_50850301_2_dialog_content = "Ah, é PlayerName!",
  ui_story_5085_50850301_3_dialog_content = "Graças a Deus você ainda está vivo!",
  ui_story_5085_50850301_4_dialog_content = "Desculpe, mas eu não desço tão fácil assim!",
  ui_story_5085_50850301_5_dialog_content = "Klaudia!",
  ui_story_5085_50850301_6_dialog_content = "Ah, Ryza!",
  ui_story_5085_50850301_7_dialog_content = "Graças a Deus... Quando todos se separaram no portal, eu não sabia o que fazer...",
  ui_story_5085_50850301_8_dialog_content = "Desculpe por fazer você se preocupar, Klaudia.",
  ui_story_5085_50850301_9_dialog_content = "Mas se eu consegui te encontrar aqui, isso significa que Patty provavelmente também está em algum lugar da ilha.",
  ui_story_5085_50850301_10_dialog_content = "Sim, eu também acho.",
  ui_story_5085_50850301_11_dialog_content = "Eu sabia que você acabaria me encontrando, então decidi ficar aqui e guardar isso para você, Ryza.",
  ui_story_5085_50850301_12_dialog_content = "É com...",
  ui_story_5085_50850301_13_dialog_content = "Um barril!",
  ui_story_5085_50850301_14_dialog_content = "Uh, não... Eu quis dizer a coisa ao lado.",
  ui_story_5085_50850301_15_dialog_content = "Ah! É... É um grande e belo caldeirão! Muito obrigado, Klaudia!",
  ui_story_5085_50850301_16_dialog_content = "Parece ser uma relíquia de uma civilização antiga, mas o tamanho e a forma são perfeitos para a alquimia.",
  ui_story_5085_50850301_17_dialog_content = "É o navio de três pernas que vi anteriormente! As ruínas devem estar bem aqui por perto.",
  ui_story_5085_50850301_18_dialog_content = "Ah, esqueci de nos apresentar! Meu nome é Vice, e este é PlayerName, nosso Navegador.",
  ui_story_5085_50850301_X18_dialog_content = "Um prazer conhecer você, Srta. Vice e Sr. Navegador. A Srta. Barbara na verdade me falou sobre você no caminho; espero que possamos nos tornar bons amigos!",
  ui_story_5085_50850301_X19_dialog_content = "Tenho certeza que você vai! Agora, não vamos desperdiçar todo o trabalho duro de Klaudia... PlayerName, você poderia usar seus poderes para sentir este caldeirão?",
  ui_story_5085_50850301_19_dialog_content = "Concordo. Não queremos que nada aconteça com Ryza uma vez que ela comece a usar isso.",
  ui_story_5085_50850301_20_dialog_content = "O que é isso? O grande e poderoso Navegador finalmente vai usar suas habilidades misteriosas?",
  ui_story_5085_50850301_21_dialog_content = "Não é nada, apenas a percepção extrassensorial usual—",
  ui_story_5085_50850301_22_option_content = "Aumento de Força!",
  ui_story_5085_50850301_23_dialog_content = "...",
  ui_story_5085_50850301_24_dialog_content = "Nós iremos?",
  ui_story_5085_50850301_25_dialog_content = "Vejo um conjunto de ruínas... com muitos vasos quebrados espalhados pelo chão...",
  ui_story_5085_50850301_26_dialog_content = "Parece que eles são parte das ruínas, afinal.",
  ui_story_5085_50850301_27_dialog_content = "Um pequeno reino insular construído com a tecnologia da antiga civilização, prosperou até...",
  ui_story_5085_50850301_28_dialog_content = "Volte. O reino precisa de você.",
  ui_story_5085_50850301_29_dialog_content = "Ah...",
  ui_story_5085_50850301_30_dialog_content = "O que houve?",
  ui_story_5085_50850301_31_dialog_content = "Você parece que viu um fantasma. Você gostaria de um pouco de água?",
  ui_story_5085_50850301_32_dialog_content = "... Não é nada. Eu apenas vi a história das ruínas, e havia muito para absorver de uma vez...",
  ui_story_5085_50850301_33_dialog_content = "De qualquer forma, não há contaminação de Darkflow no vaso, e os Eclipsitas nem sequer tocaram nele. Deve ser seguro usar.",
  ui_story_5085_50850301_34_dialog_content = "Sério? Ótimo, muito obrigado! Mas ainda assim, espero que você não esteja exagerando nisso.",
  ui_story_5085_50850301_35_dialog_content = "Estou bem, sinceramente. Além disso, estou realmente ansioso para ver como seus poderes vão melhorar nossa vida na ilha deserta!",
  ui_story_5085_50850301_36_dialog_content = "Não precisa se preocupar com isso! Comigo por perto, a sobrevivência vai ficar muito mais fácil!",
  ui_story_5085_50850301_37_dialog_content = "Mas... Ainda há um grande obstáculo para nossa sobrevivência à espreita...",
  ui_story_5085_50850301_38_dialog_content = "Essas criaturas malignas estão ficando terrivelmente inquietas. Se não fosse pelas incríveis habilidades de luta da Senhorita Barbara agora mesmo...",
  ui_story_5085_50850301_39_dialog_content = "Oh céus, eu não sou TÃO forte, sabe.",
  ui_story_5085_50850301_40_dialog_content = "Seu apoio foi o único motivo pelo qual nossa batalha correu tão bem, meu amigo!",
  ui_story_5085_50850301_41_dialog_content = "E aquela flauta... Foi tão cativante, até mesmo para um ídolo profissional como eu!",
  ui_story_5085_50850301_42_dialog_content = "Precisamos tomar algumas precauções contra os Eclipsitas. Devemos montar acampamento em um lugar que possa ser facilmente defendido.",
  ui_story_5085_50850301_43_dialog_content = "Este mundo seu... Ele tem algum item ou material para repelir monstros? Quero dizer, Eclipsitas?",
  ui_story_5085_50850301_44_dialog_content = "Duvido. Queria que houvesse algo tão fácil aqui.",
  ui_story_5085_50850301_45_dialog_content = "Hã...",
  ui_story_5085_50850301_46_dialog_content = "Qual é o problema, Klaudia?",
  ui_story_5085_50850301_47_dialog_content = "Ryza, você acha... Seremos capazes de ir para casa?",
  ui_story_5085_50850301_48_dialog_content = "Claro. Sempre voltamos das nossas aventuras, não é?",
  ui_story_5085_50850301_50_dialog_content = "Sei que já nos deparamos com alguns problemas, mas agora eu só quero aproveitar minha aventura com todos aqui!",
  ui_story_5085_50850301_51_dialog_content = "Concordo! Nada é mais divertido do que ir em aventuras com você, Ryza!",
  ui_story_5085_50850301_53_dialog_content = "Heeheehee, obrigada! Agora então, para o bem de encontrar nosso caminho de volta para casa com segurança, vamos nos juntar ao Navegador e seus amigos e procurar por Patty!",
  ui_story_5085_50850301_58_dialog_content = "Só um momento! Acho que ouvi algo terrível...",
  ui_story_5085_50850301_59_dialog_content = "Eclipsitas! E eles estão se aproximando!",
  ui_story_5085_50850301_60_dialog_content = "Graah—",
  ui_story_5085_50850301_61_dialog_content = "Cuidado, Ryza!",
  ui_story_5085_50850301_62_dialog_content = "Uau... Outra batalha?!",
  ui_story_5085_50850302_1_dialog_content = "Contemple o poder da alquimia!",
  ui_story_5085_50850302_2_dialog_content = "Graah...",
  ui_story_5085_50850302_3_dialog_content = "Ufa... Essa foi por pouco! Ainda bem que eu tinha materiais suficientes!",
  ui_story_5085_50850302_4_dialog_content = "Ei Ryza, você fez isso usando alquimia?",
  ui_story_5085_50850302_5_dialog_content = "Isso mesmo! Bastante impressionante, hein?",
  ui_story_5085_50850302_6_dialog_content = "Isso é um eufemismo, para dizer o mínimo. Com esse tipo de poder, explorar a ilha não deveria ser um desafio.",
  ui_story_5085_50850302_7_dialog_content = "No entanto, isso só resolve nossas preocupações com a luta. A senhorita Vice estava certa: precisamos encontrar um lugar adequado para montar nosso acampamento base.",
  ui_story_5085_50850302_8_dialog_content = "Sim, você está certo. Com tantos Eclipsitas vagando por aí, um lugar seguro para traçar estratégias seria muito útil.",
  ui_story_5085_50850302_9_dialog_content = "Então, alguém tem alguma sugestão para o nosso acampamento?",
  ui_story_5085_50850302_10_dialog_content = "Acho que... Em algum lugar perto da praia seria o melhor.",
  ui_story_5085_50850302_11_dialog_content = "Pelo que a senhorita Barbara e eu vimos anteriormente, grande parte desta ilha parece estar repleta de remanescentes quebrados de ruínas antigas.",
  ui_story_5085_50850302_12_dialog_content = "O mesmo pode ser verdade para os Eclipsitas...",
  ui_story_5085_50850302_13_dialog_content = "No entanto, as praias parecem estar principalmente livres desses remanescentes, o que pode significar que são nossa escolha mais segura. Não só isso, mas também podemos ficar de olho nos navios que passam.",
  ui_story_5085_50850302_14_dialog_content = "Eu estava pensando exatamente a mesma coisa!",
  ui_story_5085_50850302_15_dialog_content = "Parece que você tem um verdadeiro olho para estratégia.",
  ui_story_5085_50850302_16_dialog_content = "Você e Ryza são totalmente diferentes... É por isso que vocês se complementam tão bem!",
  ui_story_5085_50850302_17_dialog_content = "Na verdade, Ryza tem me observado todo este tempo.",
  ui_story_5085_50850302_18_dialog_content = "Do que você está falando? É você quem sempre cuida de mim.",
  ui_story_5085_50850302_19_dialog_content = "Sim, sim, entendemos que vocês dois são muito próximos! Agora vamos seguir para o nosso próximo objetivo!",
  ui_story_5085_50850302_20_dialog_content = "E isso seria - Construir um belo palco para expressar nossos sentimentos de amizade!",
  ui_story_5085_50850302_21_dialog_content = "Er, acho que ela quer dizer encontrar uma praia adequada para o nosso acampamento.",
  ui_story_5085_50850302_22_dialog_content = "O que você está fazendo, Klaudia? Você deixou cair algo?",
  ui_story_5085_50850302_23_dialog_content = "Ah, eu estava apenas procurando por aqueles remanescentes que mencionei anteriormente. Parece haver alguns deles espalhados por aí...",
  ui_story_5085_50850302_24_dialog_content = "Sempre que Ryza nos leva para uma aventura, tendemos a pegar itens aparentemente inúteis como este.",
  ui_story_5085_50850302_25_dialog_content = "Você nunca sabe... Alguns deles podem ser materiais de alquimia potentes.",
  ui_story_5085_50850302_26_dialog_content = "Entendi. Talvez eu possa usar meus poderes para procurar algo útil também!",
  ui_story_5085_50850302_27_dialog_content = "Isso parece muito com caça ao tesouro! Como nativo do Deserto Rediesel, isso acontece ser uma das minhas especialidades!",
  ui_story_5085_50850302_28_dialog_content = "Hmm... Isso parece o brinquedo de um nobre antigo... Chato!",
  ui_story_5085_50850302_29_dialog_content = "Hahaha! Acho que devo mencionar que as pessoas do Deserto Rediesel não se importam muito com nada que não possa ser encaixado em uma máquina enorme.",
  ui_story_5085_50850302_30_dialog_content = "Falando em máquinas enormes... Alguém estava procurando informações sobre mechas antigos aqui na ilha.",
  ui_story_5085_50850302_31_dialog_content = "Isso é estranho... por algum motivo, não consigo me lembrar de quem era.",
  ui_story_5085_50850302_32_dialog_content = "Sobre que tipo de coisa você está falando? Posso usar alquimia nisso?",
  ui_story_5085_50850302_33_dialog_content = "Ryza, cuidado onde pisa!",
  ui_story_5085_50850302_34_dialog_content = "... Nossa!",
  ui_story_5085_50850302_35_dialog_content = "Foi por pouco... Como é que tem gelo aqui?!",
  ui_story_5085_50850302_36_dialog_content = "Ei... Se você olhar de perto, o gelo parece estranhamente em forma de flecha...",
  ui_story_5085_50850302_37_dialog_content = "Gelo em forma de flecha? Espere... Poderia ser?!",
  ui_story_5085_50850302_38_dialog_content = "Isso deve ser obra de Zarya!",
  ui_story_5085_50850302_39_dialog_content = "Parece que ela estava deixando um rastro para trás... Tenho certeza de que a encontraremos se o seguirmos.",
  ui_story_5085_50850302_40_dialog_content = "Então, o amigo do Navegador nos deixou um sinal!",
  ui_story_5085_50850302_41_dialog_content = "Eu me pergunto se Patty fez o mesmo em algum outro lugar?",
  ui_story_5085_50850401_1_dialog_content = "Os Eclipsitas foram erradicados. Por favor, deixe outro sinal aqui, Senhorita Zarya.",
  ui_story_5085_50850401_2_dialog_content = "Ah... Claro!",
  ui_story_5085_50850401_3_dialog_content = "Há algum problema? Você parece preocupado.",
  ui_story_5085_50850401_4_dialog_content = "Não, é só que... Você é muito mais madura do que parece, Senhora Patricia.",
  ui_story_5085_50850401_5_dialog_content = "Mesmo que você não aprove totalmente o meu plano, você tem me ajudado a eliminar os Eclipsitas e deixar sinais para os outros...",
  ui_story_5085_50850401_6_dialog_content = "<size=30>Se ao menos eu pudesse ser um pouco mais maduro, também...</size>",
  ui_story_5085_50850401_7_dialog_content = "Honestamente, eu já te disse—",
  ui_story_5085_50850401_8_dialog_content = "Isso não tem nada a ver com maturidade. Uma nobre não volta atrás em sua palavra facilmente, especialmente quando ela concordou em fazer algo.",
  ui_story_5085_50850401_9_dialog_content = "Além disso, você não precisa me tratar assim. Você pode apenas...",
  ui_story_5085_50850401_10_dialog_content = "Ei—",
  ui_story_5085_50850401_11_dialog_content = "Zarya—Aqui—",
  ui_story_5085_50850401_12_dialog_content = "É PlayerName!",
  ui_story_5085_50850401_13_dialog_content = "Se alguém nos encontrou, então isso significa...",
  ui_story_5085_50850401_14_dialog_content = "Os marcadores de gelo... Eles funcionaram!",
  ui_story_5085_50850401_15_dialog_content = "Patty! Finalmente te encontramos!",
  ui_story_5085_50850401_16_dialog_content = "Ryza?! Oh...",
  ui_story_5085_50850401_17_dialog_content = "Tive a sensação de que você também estava na ilha! Esta é uma reunião bastante louca, hein?",
  ui_story_5085_50850401_18_dialog_content = "Graças a Deus você está seguro, Patricia.",
  ui_story_5085_50850401_19_dialog_content = "Estou apenas feliz que todos nós nos encontramos... Então, posso perguntar quem são seus amigos?",
  ui_story_5085_50850401_20_dialog_content = "<color=#e8d9bb>Após trocar breves apresentações, Patricia explica sua situação anterior.</color>",
  ui_story_5085_50850401_21_dialog_content = "Entendo. Então você tem trabalhado com este Navegador desde que fomos transportados para este mundo.",
  ui_story_5085_50850401_22_dialog_content = "Você sempre parece atrair outros aventureiros onde quer que vá, Ryza. É realmente incrível.",
  ui_story_5085_50850401_23_dialog_content = "Não é só comigo, sabe. Nossos amigos aqui acontecem de ter objetivos semelhantes aos nossos!",
  ui_story_5085_50850401_24_dialog_content = "Entendo agora. Por favor, permita-me apresentar-me mais uma vez: Eu sou Patricia Abelheim, mas você pode me chamar de Patty para abreviar. É uma honra conhecer todos vocês.",
  ui_story_5085_50850401_25_dialog_content = "Uau, que introdução... Ela soa exatamente como uma cavaleira!",
  ui_story_5085_50850401_26_dialog_content = "Isso é porque Patty é uma nobre!",
  ui_story_5085_50850401_27_dialog_content = "Entendi, isso explica porque ela me lembra de um certo amigo! Ela também é uma nobre digna, além de uma cavaleira incrível!",
  ui_story_5085_50850401_28_dialog_content = "E com isso, todos os meus amigos estão contabilizados! E você, Navegador?",
  ui_story_5085_50850401_29_dialog_content = "Vamos ver...",
  ui_story_5085_50850401_30_dialog_content = "Com o Zarya encontrado, nosso grupo também deve estar completo agora.",
  ui_story_5085_50850401_31_dialog_content = "Hmm... Talvez devêssemos fazer uma última contagem, só para ter certeza?",
  ui_story_5085_50850401_32_dialog_content = "Um, dois, três, quatro! Sim, estamos todos aqui!",
  ui_story_5085_50850401_33_dialog_content = "Apenas quatro? Sinto que estamos perdendo alguém...",
  ui_story_5085_50850401_34_dialog_content = "Talvez você esteja apenas pensando em Corax? Ele disse que queria vir também, lembra?",
  ui_story_5085_50850401_35_dialog_content = "Você está certo... Talvez eu esteja pensando demais nas coisas.",
  ui_story_5085_50850401_36_dialog_content = "Acho que estamos bem agora, Ryza. Qual é o seu próximo passo?",
  ui_story_5085_50850401_37_dialog_content = "Primeiro, preciso recuperar aquele caldeirão e levá-lo a uma praia adequada. Depois disso, posso criar um ateliê para usarmos!",
  ui_story_5085_50850401_38_dialog_content = "Uma vez que tenhamos isso, vamos descansar, criar muitos itens úteis e continuar com nossa exploração das ruínas!",
  ui_story_5085_50850401_39_dialog_content = "O que todos pensam do plano até agora?",
  ui_story_5085_50850401_40_dialog_content = "Mesmo que estejamos em um mundo completamente desconhecido... Ryza está tão motivado como sempre.",
  ui_story_5085_50850401_41_dialog_content = "Sem objeções aqui. Acredito que um Atelier será essencial para encontrar nosso caminho de volta para casa.",
  ui_story_5085_50850401_42_dialog_content = "Concordo. As ruínas da ilha relacionadas à música antiga também são dignas de investigação.",
  ui_story_5085_50850401_43_dialog_content = "Acredito que o plano de Ryza é bom.",
  ui_story_5085_50850401_44_dialog_content = "Assim como eu.",
  ui_story_5085_50850401_45_dialog_content = "Ótimo! Eu adoraria manter as chamas da nossa aventura de verão bem quentes também! E você, Navegador?",
  ui_story_5085_50850401_46_dialog_content = "Também viemos explorar essas ruínas.",
  ui_story_5085_50850401_47_dialog_content = "Mas ainda há a questão de como vamos retornar ao continente...",
  ui_story_5085_50850401_48_dialog_content = "De qualquer forma, não podemos nos dar ao luxo de voltar agora!",
  ui_story_5085_50850401_49_dialog_content = "Se voltarmos para casa de mãos vazias, perderemos nosso pagamento E teremos que pagar pelo navio... Ah, se eu soubesse que algo assim iria acontecer, teria comprado seguro contra desastres lá em Umbraton...",
  ui_story_5085_50850401_50_dialog_content = "Além disso, talvez encontraremos um navio ou algum tipo de dispositivo de comunicação nas ruínas?",
  ui_story_5085_50850401_51_dialog_content = "... Você está certo. Não consigo pensar em uma solução melhor agora mesmo...",
  ui_story_5085_50850401_52_dialog_content = "Nesse caso, vamos nos juntar à exploração e completar nossa missão!",
  ui_story_5085_50850401_53_dialog_content = "Uau, parece que todos estão animados! Agora então... Estamos indo para a praia—",
  ui_story_5085_50850401_54_dialog_content = "Vamos láaaaa!",
  ui_story_5085_50850501_1_dialog_content = "Ha—Ufa—!",
  ui_story_5085_50850501_2_dialog_content = "Este lugar deve servir perfeitamente! Obrigado novamente a todos!",
  ui_story_5085_50850501_3_dialog_content = "Nunca sequer considerei usar o gelo de Zarya desta maneira. Nós realmente transportamos o caldeirão até aqui com a ajuda do gelo...",
  ui_story_5085_50850501_4_dialog_content = "N-Não é nada, realmente. Meus poderes não são bons para muito mais do que isso...",
  ui_story_5085_50850501_5_dialog_content = "Parece que tudo vai dar certo uma vez que Ryza seja capaz de realizar sua alquimia.",
  ui_story_5085_50850501_6_dialog_content = "Heheh, é isso mesmo. A alquimia de Ryza é algo verdadeiramente incrível.",
  ui_story_5085_50850501_7_dialog_content = "Quanto a um local adequado para o ateliê, dê uma olhada neste lugar, Ryza—",
  ui_story_5085_50850501_8_dialog_content = "Esta parte da floresta oferece bastante luz solar e água limpa facilmente disponível. É um lugar valioso para montar um abrigo.",
  ui_story_5085_50850501_9_dialog_content = "A praia também fica perto, o que nos permite ver o oceano a qualquer momento.",
  ui_story_5085_50850501_11_dialog_content = "Não vejo por que não! Tenho certeza de que todos apreciariam uma agradável cabana à beira-mar na floresta!",
  ui_story_5085_50850501_12_dialog_content = "Estou pronto para começar a sintetizar tudo o que precisamos para construir nossa casa de campo.",
  ui_story_5085_50850501_13_dialog_content = "Então eu vou buscar o Navegador. Ele tem querido ver a alquimia do Ryza há muito tempo.",
  ui_story_5085_50850501_14_dialog_content = "É isso—?",
  ui_story_5085_50850501_15_dialog_content = "Uau! Tem tanto!!!",
  ui_story_5085_50850501_16_dialog_content = "Todos os tipos de materiais de construção, cortados e moldados com especificações exatas... E ela continua tirando-os do caldeirão!",
  ui_story_5085_50850501_17_dialog_content = "Tudo o que fizemos foi jogar um monte de coisas aleatórias e comuns...",
  ui_story_5085_50850501_18_dialog_content = "E-Então este é o poder da alquimia! É tão útil! Você poderia construir uma casa inteira sem nem mesmo suar...",
  ui_story_5085_50850501_19_dialog_content = "Não fique aí parado enquanto a Senhorita Ryza faz todo o trabalho, todos! Vamos começar a construir esse ateliê!",
  ui_story_5085_50850501_20_dialog_content = "Aí vem eles!",
  ui_story_5085_50850501_21_dialog_content = "Eu posso lidar com a movimentação de toda a madeira, então apenas deixe comigo!",
  ui_story_5085_50850501_22_dialog_content = "Está tudo bem? Eles são incrivelmente pesados...",
  ui_story_5085_50850501_23_dialog_content = "Talvez eu devesse fazer isso no lugar? Pedir para uma ídola pequena carregar vigas de madeira parece um pouco errado.",
  ui_story_5085_50850501_24_dialog_content = "É mesmo? Humph! Não ouse subestimar o ídolo número um do Deserto Rediesel! Arrrrraaaaaagh—",
  ui_story_5085_50850501_25_dialog_content = "<color=#e8d9bb>Estrondo—Estalo—Surdo—!</color>",
  ui_story_5085_50850501_26_dialog_content = "I-Incrível! Ela conseguiu carregar todos aqueles materiais de construção apesar de seu pequeno físico...",
  ui_story_5085_50850501_27_dialog_content = "O que você está fazendo, Zarya?",
  ui_story_5085_50850501_28_dialog_content = "Eu? Er... Estou usando meu gelo para criar estruturas de suporte para todos e para refrescar a área.",
  ui_story_5085_50850501_29_dialog_content = "Foi ideia da Patty.",
  ui_story_5085_50850501_30_dialog_content = "É difícil não ficar impressionado depois de ver do que você é capaz de fazer, Senhorita Zarya.",
  ui_story_5085_50850501_31_dialog_content = "Apesar de ter a <color=#FFB400>mesma idade</color> que eu, seus poderes são muito superiores aos meus... É algo verdadeiramente incrível.",
  ui_story_5085_50850501_32_dialog_content = "...",
  ui_story_5085_50850501_33_dialog_content = "Er... Eu disse algo errado?",
  ui_story_5085_50850501_34_dialog_content = "Eu não sei, você fez?",
  ui_story_5085_50850501_35_dialog_content = "Uh, pode ser porque você mencionou a idade dela...",
  ui_story_5085_50850501_36_dialog_content = "A idade da senhorita Zarya? Você está me dizendo... Ela e eu não somos realmente tão próximos em idade?!",
  ui_story_5085_50850501_37_dialog_content = "Oh garoto...",
  ui_story_5085_50850501_39_dialog_content = "...",
  ui_story_5085_50850501_40_dialog_content = "<size=30>Eu sou <color=#FFB400>117</color>...</size>",
  ui_story_5085_50850501_41_dialog_content = "<size=50>?!?!</size>",
  ui_story_5085_50850501_42_dialog_content = "Ela realmente encontrou a coragem para dizer isso!",
  ui_story_5085_50850501_X42_dialog_content = "Heheh, espero que eu não esteja te assustando.",
  ui_story_5085_50850501_X43_dialog_content = "Não vou mentir, foi um pouco assustador. Mas quando penso nisso, temos um amigo que não parece nada com a idade real dele também.",
  ui_story_5085_50850501_X44_dialog_content = "Isso é verdade.",
  ui_story_5085_50850501_X45_dialog_content = "Agora que você mencionou, você está certo.",
  ui_story_5085_50850501_43_dialog_content = "Ahhhh—Vamos apenas esquecer isso e seguir em frente! Ainda precisamos construir este ateliê!!!",
  ui_story_5085_50850501_44_dialog_content = "Finalmente terminamos, e o caldeirão está exatamente onde precisa estar!",
  ui_story_5085_50850501_45_dialog_content = "Deleite seus olhos com o único Atelier deste mundo, trazido para você por ninguém menos que Ryza Stout!",
  ui_story_5085_50850501_46_dialog_content = "E com nosso trabalho finalmente completo...",
  ui_story_5085_50850501_47_dialog_content = "É hora de se divertir de verdade no verão! Deixe o cozimento comigo; Eu quero mostrar a todos como nós grelhamos comida de volta no Deserto Rediesel!",
  ui_story_5085_50850501_48_dialog_content = "Tudo bem, vou vasculhar a praia em busca de materiais e ingredientes para comida.",
  ui_story_5085_50850501_49_dialog_content = "E eu vou... fazer algumas sobremesas com os ingredientes de todos.",
  ui_story_5085_50850501_50_dialog_content = "Não estou com vontade de entrar na água, então vou apenas ajudar a preparar a comida.",
  ui_story_5085_50850501_51_dialog_content = "Ah, vamos lá, Patty! Não é divertido a menos que todos nós vamos brincar na praia juntos...",
  ui_story_5085_50850501_52_dialog_content = "Hum... Ryza? Acho que estamos esquecendo de algo muito importante...",
  ui_story_5085_50850501_53_dialog_content = "Quando viemos para este mundo, não trouxemos nenhum traje de banho.",
  ui_story_5085_50850501_54_dialog_content = "Você está certo... Nós sempre poderíamos reunir materiais para eu fazer alguns... Mas estará escuro quando eu terminar.",
  ui_story_5085_50850501_55_dialog_content = "Ah! Na verdade... Eu aconteço ter um maiô extra comigo.",
  ui_story_5085_50850501_56_dialog_content = "S-sério?",
  ui_story_5085_50850501_57_dialog_content = "Uh-huh! Eu pretendia dar isso para Carleen como um presente... Ela é outra amiga próxima nossa.",
  ui_story_5085_50850501_58_dialog_content = "Mas ela está sempre tão ocupada com o trabalho e outros assuntos oficiais. Ela pode não ter a chance de usá-lo antes do fim do verão.",
  ui_story_5085_50850501_59_dialog_content = "Se estiver tudo bem para você, você é mais do que bem-vindo para usá-lo.",
  ui_story_5085_50850501_60_dialog_content = "<color=#e8d9bb>Um tempo depois—</color>",
  ui_story_5085_50850501_61_dialog_content = "Ahh!!",
  ui_story_5085_50850501_62_dialog_content = "Qual é o problema?!",
  ui_story_5085_50850501_63_dialog_content = "Esse maiô está incrível! Obrigado!",
  ui_story_5085_50850502_1_dialog_content = "Hora de brincar na água!",
  ui_story_5085_50850502_2_dialog_content = "Uau, que frio! Tem certeza de que não quer se juntar a nós, Patty?",
  ui_story_5085_50850502_3_dialog_content = "Positivo. Sem nenhum maiô extra... Eu me recuso a me envergonhar na frente de todos.",
  ui_story_5085_50850502_4_dialog_content = "Sério? Que pena, mas tudo bem! Por aqui, todos; aqui estão os materiais que vamos precisar...",
  ui_story_5085_50850502_5_dialog_content = "<color=#e8d9bb>Resumo—</color>",
  ui_story_5085_50850502_6_dialog_content = "Uau! S-Senhora Barbara?! O que você está...",
  ui_story_5085_50850502_7_dialog_content = "Eu pensei que estávamos brincando, não estávamos? Melhor se mexer, ou eu realmente vou te pegar! Hah!",
  ui_story_5085_50850502_8_dialog_content = "<color=#e8d9bb>Respingo—!</color>",
  ui_story_5085_50850502_9_dialog_content = "Heh... Nesse caso, eu também não vou me segurar! Hyaah!",
  ui_story_5085_50850502_10_dialog_content = "Ah! E-Espere um minuto, ainda não estou mentalmente preparado para isso...!",
  ui_story_5085_50850502_11_dialog_content = "Não é hora para brincadeiras... Agora me cubra, PlayerName!",
  ui_story_5085_50850502_12_dialog_content = "<color=#e8d9bb>Respingo—!</color>",
  ui_story_5085_50850502_13_dialog_content = "...",
  ui_story_5085_50850502_14_dialog_content = "Então é assim, hein...",
  ui_story_5085_50850502_15_dialog_content = "Espero que todos estejam prontos para perder!!!",
  ui_story_5085_50850502_16_dialog_content = "<color=#e8d9bb>Respingo—!</color>",
  ui_story_5085_50850502_17_dialog_content = "<color=#e8d9bb>O sol se põe lentamente enquanto eles brincam e reúnem ingredientes para um delicioso churrasco. Quando suas barrigas estão cheias, a noite já caiu.</color>",
  ui_story_5085_50850502_18_dialog_content = "É bom finalmente relaxar depois de um dia tão longo e estressante...",
  ui_story_5085_50850502_19_dialog_content = "Eu não percebi que minhas bebidas seriam tão populares, senão teria feito mais! Felizmente, a ilha oferece alguns ingredientes verdadeiramente frescos.",
  ui_story_5085_50850502_20_dialog_content = "Naturalmente, temos que agradecer a todos os outros por explorarem esses materiais, e à Srta. Zarya por fornecer o gelo!",
  ui_story_5085_50850502_21_dialog_content = "Não foi nada... Você é realmente talentosa quando se trata de fazer bebidas, Senhorita Klaudia!",
  ui_story_5085_50850502_22_dialog_content = "Valeu... Mesmo que nós...",
  ui_story_5085_50850502_23_dialog_content = "Mesmo que tenhamos passado tanto tempo jogando que esquecemos de reunir mais materiais...",
  ui_story_5085_50850502_24_dialog_content = "Acho que a diversão que tivemos e as memórias que criamos são ainda mais importantes!",
  ui_story_5085_50850502_25_dialog_content = "Permita-me agradecer a todos novamente por experimentarem minha lula especial Rediesel! Coloquei meu coração e alma para fazê-la hoje!",
  ui_story_5085_50850502_26_dialog_content = "Mesmo que não houvesse realmente o suficiente para todos, e algumas das peças ficaram um pouco chamuscadas...",
  ui_story_5085_50850502_27_dialog_content = "O sabor ainda era de outro mundo! Se ao menos pudéssemos usar a alquimia para restaurar suas partes externas...",
  ui_story_5085_50850502_28_dialog_content = "Falando nisso... a alquimia pode ser usada para restaurar esses fragmentos de relíquias à sua forma original?",
  ui_story_5085_50850502_29_dialog_content = "Ah, essas são as peças que coletamos mais cedo.",
  ui_story_5085_50850502_30_dialog_content = "Peguei alguns eu mesmo, mas não tenho certeza se Ryza pode usá-los ou não.",
  ui_story_5085_50850502_31_dialog_content = "Vocês são todos ajudantes maravilhosos! Obrigado por ficarem de olho em novos materiais para a minha alquimia!",
  ui_story_5085_50850502_32_dialog_content = "Não saberemos a menos que tentemos, certo? Vou ver o que posso fazer com essas peças hoje à noite!",
  ui_story_5085_50850502_33_dialog_content = "Desde que conheci Ryza, parece que finalmente tenho uma competição séria quando se trata de vasculhar!",
  ui_story_5085_50850502_34_dialog_content = "Hahaha, isso pode nos dar mais informações sobre as ruínas.",
  ui_story_5085_50850502_35_dialog_content = "Não consigo sentir nada desses fragmentos individuais.",
  ui_story_5085_50850502_36_dialog_content = "Mas uma vez que eles tenham sido restaurados... Pode ser uma história completamente diferente!",
  ui_story_5085_50850502_37_dialog_content = "Vou arrumar o ateliê para que todos possam ter uma boa noite de descanso.",
  ui_story_5085_50850601_1_dialog_content = "<color=#e8d9bb>Quá—Quá—</color>",
  ui_story_5085_50850601_2_dialog_content = "... Huh?! Ah... Acho que eles têm pássaros marinhos noturnos neste mundo também...",
  ui_story_5085_50850601_3_dialog_content = "Tudo bem, eles não devem acordar ninguém.",
  ui_story_5085_50850601_4_dialog_content = "Todos estão exaustos depois de hoje... Eles estão todos dormindo profundamente.",
  ui_story_5085_50850601_5_dialog_content = "Você ainda está vigiando o caldeirão, Ryza?",
  ui_story_5085_50850601_6_dialog_content = "Isso mesmo! Tenho que ficar de olho no conteúdo para garantir que nada dê errado.",
  ui_story_5085_50850601_7_dialog_content = "Hum, nada mal mesmo... Um pouco mais e os fragmentos devem voltar à sua forma original!",
  ui_story_5085_50850601_8_dialog_content = "Parece que você não é estranho em mexer um caldeirão a noite toda. Ser um alquimista deve ser realmente difícil...",
  ui_story_5085_50850601_9_dialog_content = "A alquimia é a arte de criar algo do nada. Ao longo dos séculos, os alquimistas experimentaram inúmeras ideias e métodos para nos dar o conhecimento que temos hoje.",
  ui_story_5085_50850601_10_dialog_content = "Ahhh, mas ainda não consigo deixar de me preocupar. O que faremos se algo der errado...?",
  ui_story_5085_50850601_11_dialog_content = "Haha, então vou ficar acordado com você até terminar. Tenho certeza que tudo vai ficar bem!",
  ui_story_5085_50850601_12_dialog_content = "Na verdade, quando usei meus poderes para sentir este caldeirão... Ouvi uma voz estranha.",
  ui_story_5085_50850601_13_dialog_content = "Ele me disse para voltar.",
  ui_story_5085_50850601_14_dialog_content = "Eh?!",
  ui_story_5085_50850601_15_dialog_content = "É mesmo? Você acha que era o caldeirão falando com você?",
  ui_story_5085_50850601_16_dialog_content = "Talvez. Meus poderes psíquicos me dizem que essa voz está de alguma forma conectada às ruínas.",
  ui_story_5085_50850601_17_dialog_content = "Soou como um espírito antigo... E tentou se comunicar comigo falando como se me conhecesse.",
  ui_story_5085_50850601_18_dialog_content = "Não tenho certeza se devo ou não seguir essa pista. Eu nem sei por onde poderia começar...",
  ui_story_5085_50850601_19_dialog_content = "Eu tenho uma pergunta!",
  ui_story_5085_50850601_20_dialog_content = "É sobre seus poderes. Se você não consegue sentir nenhum Eclipsita por perto, então isso significa que não vamos encontrar nenhum, certo?",
  ui_story_5085_50850601_21_dialog_content = "Sim, isso geralmente é o caso...",
  ui_story_5085_50850601_22_dialog_content = "Entendo. Que poder interessante... Hah!",
  ui_story_5085_50850601_23_dialog_content = "<color=#e8d9bb>Pimba!</color>",
  ui_story_5085_50850601_24_dialog_content = "O-O que foi isso...?!",
  ui_story_5085_50850601_25_dialog_content = "Não se preocupe, era apenas um bug. Parece que existem algumas coisas que até mesmo seus poderes não conseguem detectar, hein?",
  ui_story_5085_50850601_26_dialog_content = "Parece um mosquito, mas olhe mais de perto! Seus olhos são completamente vermelhos e ele desaparece logo depois que eu o matei... Há uma boa chance de ser algum tipo de mosquito Eclipsita.",
  ui_story_5085_50850601_27_dialog_content = "E ainda assim você nem percebeu! Isso poderia significar que a ilha possui outras propriedades únicas?",
  ui_story_5085_50850601_28_dialog_content = "Com certeza é o que parece...",
  ui_story_5085_50850601_29_dialog_content = "Esta ilha realmente está cheia de mistérios.",
  ui_story_5085_50850601_30_dialog_content = "Concordo, e algo me diz que a ilha e suas ruínas também querem que descubramos seus segredos.",
  ui_story_5085_50850601_32_dialog_content = "É engraçado, você estava me contando sua história antes daquele pássaro interromper...",
  ui_story_5085_50850601_33_dialog_content = "Mas agora, você está me ouvindo falar sobre minhas preocupações...",
  ui_story_5085_50850601_35_dialog_content = "Se algum dia encontrarmos tempo, ainda quero ouvir mais sobre suas aventuras!",
  ui_story_5085_50850601_37_dialog_content = "Parece que você realmente ama aventuras, Ryza.",
  ui_story_5085_50850601_38_dialog_content = "Mas eu posso me relacionar totalmente, porque eu também!",
  ui_story_5085_50850601_39_dialog_content = "Seja vendo coisas novas estranhas ou viajando com meus amigos... Eu sempre valorizo cada momento de cada aventura!",
  ui_story_5085_50850601_40_dialog_content = "<color=#e8d9bb>Entre os dois espíritos afins, o caldeirão de alquimia parece ressoar com sua paixão por aventura e faz um som promissor.</color>",
  ui_story_5085_50850601_41_dialog_content = "Conseguimos!",
  ui_story_5085_50850601_42_dialog_content = "Os fragmentos foram restaurados à sua forma original... Espere, agora são três! Alguma ideia do que seja isso?",
  ui_story_5085_50850601_43_dialog_content = "É com...",
  ui_story_5085_50850601_44_dialog_content = "... Algum tipo de <color=#FFB400>emblema</color>?",
  ui_story_5085_50850601_45_dialog_content = "É, e existem três tipos diferentes deles! Todos são tão bonitos!",
  ui_story_5085_50850601_46_dialog_content = "Confira este aqui! Parece que algo está gravado nele... Um escudo, talvez? Eu me pergunto o que isso poderia significar?",
  ui_story_5085_50850601_47_dialog_content = "Deixe-me tentar sentir isso.",
  ui_story_5085_50850601_48_option_content = "Aumento de Força",
  ui_story_5085_50850601_49_dialog_content = "Meu príncipe, não temos muito tempo. Devemos tomar uma decisão antes que seja tarde demais.",
  ui_story_5085_50850601_50_dialog_content = "A relíquia antiga que você nos apresentou funciona muito bem, mas ainda temos que dominar seus controles.",
  ui_story_5085_50850601_51_dialog_content = "As fileiras dos Eclipsitas aumentam a cada dia que passa, e estamos desolados ao vê-lo em um estado tão desgastado e ansioso...",
  ui_story_5085_50850601_52_dialog_content = "O Músico nos conta que você planeja deixar o reino e viajar para uma terra distante.",
  ui_story_5085_50850601_53_dialog_content = "Mas não importa o que aconteça, Alteza... Sempre honraremos sua decisão...",
  ui_story_5085_50850601_54_dialog_content = "São estas as memórias do cavaleiro naquele emblema? Parece que ele está falando sobre as ruínas da ilha... Isso pode até nos dizer mais sobre a teleportação!",
  ui_story_5085_50850601_55_dialog_content = "Por favor, você pode me mostrar como usar o poder das ruínas?",
  ui_story_5085_50850601_56_dialog_content = "Volte.",
  ui_story_5085_50850601_57_dialog_content = "... Aquela voz novamente! Quem é você?! Será que você é...",
  ui_story_5085_50850601_58_dialog_content = "Volte! Sua glória espera...!",
  ui_story_5085_50850601_59_dialog_content = "<size=50>\"Pois quando o príncipe errante retornar, também retornará a glória do nosso reino!\"</size>",
  ui_story_5085_50850601_60_dialog_content = "... Hã?!?",
  ui_story_5085_50850601_61_option_content = "Mente... Mindlink!",
  ui_story_5085_50850601_62_dialog_content = "Ugh...",
  ui_story_5085_50850601_63_dialog_content = ".. PlayerName! O que foi?!",
  ui_story_5085_50850601_64_dialog_content = "Não tente fazer tudo sozinho! Você ainda tem a mim, assim como o resto dos nossos amigos!",
  ui_story_5085_50850601_65_dialog_content = "... Amigos...",
  ui_story_5085_50850601_66_dialog_content = "Há rumores de mechs antigos nas ruínas. Minha curiosidade estava me dominando. Eu tinha que ver por mim mesmo.",
  ui_story_5085_50850601_67_dialog_content = "Ou alguns mechas antigos lendários!",
  ui_story_5085_50850601_68_dialog_content = "... É o Fleur! Esta é a voz do Fleur! O que você fez com ele?!",
  ui_story_5085_50850601_69_dialog_content = "Volte... Retorne... para as ruínas...",
  ui_story_5085_50850601_70_dialog_content = "Não, fique longe! As ruínas são perigosas! A consciência alojada nelas alterou minhas memórias e assumiu o controle do meu corpo!",
  ui_story_5085_50850601_71_dialog_content = "Seja lá o que você fizer... Não chegue perto das ruínas!!!",
  ui_story_5085_50850601_72_dialog_content = "!!!",
  ui_story_5085_50850601_73_dialog_content = "PlayerName! Sai dessa!",
  ui_story_5085_50850601_74_dialog_content = "Eclipsitas apareceram enquanto você estava usando seus poderes! Temos que lutar!",
  ui_story_5085_50850602_1_dialog_content = "Hah! Não há escapatória!",
  ui_story_5085_50850602_2_dialog_content = "Ryza! Navegador!",
  ui_story_5085_50850602_3_dialog_content = "Ouvimos uma perturbação por aqui! Algum de vocês se machucou?",
  ui_story_5085_50850602_4_dialog_content = "Não, estamos bem...",
  ui_story_5085_50850602_5_dialog_content = "Um enorme barulho acabou de rugir por toda a ilha, como se a coisa toda começasse a se mover ou algo assim.",
  ui_story_5085_50850602_6_dialog_content = "Os Eclipsitas também parecem muito mais agitados.",
  ui_story_5085_50850602_7_dialog_content = "Uau, eu me pergunto se tropeçamos em mais um segredo?",
  ui_story_5085_50850602_8_dialog_content = "Qu-Que tipo de segredo você está falando?!",
  ui_story_5085_50850602_9_dialog_content = "Tem a ver com os emblemas que restauramos e o reino que costumava existir aqui... E também o que esta ilha fez conosco!",
  ui_story_5085_50850602_10_dialog_content = "<color=#e8d9bb>Sob a luz da lua sombria, a história do antigo reino é lentamente revelada a todos...</color>",
  ui_story_5085_50850602_11_dialog_content = "... E é mais ou menos isso que aconteceu. Temos que resgatar Fleur e nos livrar da presença malévola que está controlando seu corpo!",
  ui_story_5085_50850602_12_dialog_content = "Uma magia que pode apagar as memórias dos amigos... Que desprezível.",
  ui_story_5085_50850602_13_dialog_content = "Mesmo lembrando dele agora, ainda me sinto péssimo por ter esquecido...",
  ui_story_5085_50850602_14_dialog_content = "Como ousam essas ruínas fedorentas lançar um feitiço em mim! Marquem minhas palavras, vou transformá-las em uma pilha ainda maior de escombros antes de terminarmos aqui!",
  ui_story_5085_50850602_15_dialog_content = "Então parece... O poder dessas ruínas é o que nos trouxe aqui do nosso próprio mundo...",
  ui_story_5085_50850602_17_dialog_content = "Com base no que Ryza e o Navegador, esses três emblemas podem ser a chave para derrotar as ruínas.",
  ui_story_5085_50850602_18_dialog_content = "Não importa o que essa coisa possa ser, não chegaremos a lugar algum a menos que a investiguemos por nós mesmos!",
  ui_story_5085_50850602_20_dialog_content = "Concordo. Seja o ressentimento persistente de alguém ou a tecnologia do passado, sempre há uma solução. Agora vamos nos preparar para ir!",
  ui_story_5085_50850602_21_dialog_content = "Enquanto todos estão fazendo suas preparações, vou sentir os outros dois emblemas e ver o que mais posso encontrar.",
  ui_story_5085_50850701_1_dialog_content = "Aumento de Força",
  ui_story_5085_50850701_2_dialog_content = "Três emblemas... correspondem aos três companheiros mais próximos do príncipe.",
  ui_story_5085_50850701_3_dialog_content = "Um cavaleiro valente que combate inimigos com sua espada...",
  ui_story_5085_50850701_4_dialog_content = "Um mago que estuda a história antiga em busca de sabedoria arcana...",
  ui_story_5085_50850701_5_dialog_content = "E um músico da corte, cujas melodias podem encorajar até mesmo os corações mais hesitantes...",
  ui_story_5085_50850701_6_dialog_content = "Eles eram os súditos mais leais do príncipe, e lutaram ao seu lado nos momentos bons e ruins.",
  ui_story_5085_50850701_7_dialog_content = "Mas quando ele partiu, os três ficaram para trás para anunciar seu retorno...",
  ui_story_5085_50850701_8_dialog_content = "\"Porque quando o príncipe errante retornar, também retornará a glória do nosso reino!\"",
  ui_story_5085_50850701_9_dialog_content = "Entendi. Então é isso que significa.",
  ui_story_5085_50850701_10_dialog_content = "Mas o reino agora não passa de ruínas... E além disso, as ruínas perderam completamente o controle.",
  ui_story_5085_50850701_11_dialog_content = "Isso significa que o príncipe nunca retornou, mesmo que seu reino estivesse sob ataque dos Eclipsitas?",
  ui_story_5085_50850701_12_dialog_content = "Enquanto isso, seus três amigos mais próximos ficaram na ilha à espera dele...",
  ui_story_5085_50850701_13_dialog_content = "Mas agora que nenhum deles está aqui, a consciência dentro das ruínas começou lentamente a perder o controle...",
  ui_story_5085_50850701_14_dialog_content = "Escolhendo aleatoriamente para sequestrar pessoas em nome do príncipe?",
  ui_story_5085_50850701_16_dialog_content = "Por que ele abandonaria a ilha quando tinha a proteção tanto das antigas ruínas quanto de seus amigos mais próximos?",
  ui_story_5085_50850701_18_dialog_content = "Ele pode parecer um covarde... Mas talvez ele tivesse um motivo para não retornar?",
  ui_story_5085_50850701_19_dialog_content = "Bem, não vamos nos aproximar da verdade se continuarmos sentados e adivinhando assim.",
  ui_story_5085_50850701_20_dialog_content = "As respostas provavelmente estão nos esperando no fim de nossa aventura.",
  ui_story_5085_50850701_21_dialog_content = "Está certo! Nossa missão é desvendar os segredos dessas ruínas e resgatar o amigo do Navegador!",
  ui_story_5085_50850701_22_dialog_content = "Concordo. O caminho à frente não será fácil, mas não podemos nos dar ao luxo de recuar.",
  ui_story_5085_50850702_1_dialog_content = "<color=#e8d9bb>Enquanto avançávamos pela floresta, mantive minha mente alerta para qualquer sinal do nosso objetivo.</color>",
  ui_story_5085_50850702_2_dialog_content = "<color=#e8d9bb>Mas quando alcançamos o topo da montanha, as ruínas finalmente passaram a ser avistadas.</color>",
  ui_story_5085_50850702_3_dialog_content = "Nós... Nós finalmente... chegamos a este ponto!",
  ui_story_5085_50850702_4_dialog_content = "Este antigo portão de pedra é a entrada para as ruínas? Se sim... Como vamos entrar...?",
  ui_story_5085_50850702_5_dialog_content = "Ei! Olhem para essas fendas no portão, pessoal!",
  ui_story_5085_50850702_6_dialog_content = "Eles parecem combinar perfeitamente com a forma daqueles três emblemas! Talvez eles realmente sejam as chaves!",
  ui_story_5085_50850702_7_dialog_content = "PlayerName, você consegue sentir se há algum Eclipsita por perto?",
  ui_story_5085_50850702_8_option_content = "Mindlink!",
  ui_story_5085_50850702_9_dialog_content = "Não há nenhum Eclipsita do outro lado do portão, mas...",
  ui_story_5085_50850702_10_dialog_content = "Com certeza tem algo ali...",
  ui_story_5085_50850702_11_dialog_content = "Você também pode sentir, Ryza?",
  ui_story_5085_50850702_12_dialog_content = "Talvez seja porque estou segurando este emblema, mas sinto um forte sentimento de anseio vindo do outro lado. É tão triste... E ainda assim estranhamente reconfortante.",
  ui_story_5085_50850702_13_dialog_content = "Vamos apenas colocar os emblemas no lugar primeiro.",
  ui_story_5085_50850702_14_dialog_content = "<color=#e8d9bb>Clique, clique, clique—</color>",
  ui_story_5085_50850702_15_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_5085_50850702_16_dialog_content = "O-O que está acontecendo?!",
  ui_story_5085_50850702_17_dialog_content = "Espere... Alguém está vindo!",
  ui_story_5085_50850702_18_dialog_content = "Lá em cima!!",
  ui_story_5085_50850702_19_dialog_content = "Você está certo... Mas quando eles apareceram?!",
  ui_story_5085_50850702_20_dialog_content = "Bem-vindo ao meu reino—",
  ui_story_5085_50850702_21_dialog_content = "F-Fleur?!",
  ui_story_5085_50850702_22_dialog_content = "Não, é a consciência dentro das ruínas! Está controlando o corpo do Fleur...",
  ui_story_5085_50850702_23_dialog_content = "E forçando-o a agir como o \"príncipe errante\"!",
  ui_story_5085_50850702_24_dialog_content = "Desejo-lhe bom dia, meu amigo Celestita errante.",
  ui_story_5085_50850702_25_dialog_content = "Os atores nesta peça importam pouco. Na busca por você, ele tropeçou neste lugar...",
  ui_story_5085_50850702_26_dialog_content = "E assim as ruínas o designaram como príncipe.",
  ui_story_5085_50850702_27_dialog_content = "Ah—Como lamentei a perda do meu reino, e como nem uma alma veio em sua defesa! Mas agora, chegou a hora de convocar meus súditos mais leais.",
  ui_story_5085_50850702_28_option_content = "Aumento de Força!",
  ui_story_5085_50850702_29_dialog_content = "Fleur! Sair dessa!",
  ui_story_5085_50850702_30_dialog_content = "Uau—",
  ui_story_5085_50850702_31_dialog_content = "Minha cabeça... Está latejando de repente...",
  ui_story_5085_50850702_32_dialog_content = "S-Seu poder não está funcionando, ! Usá-los só fará o \"príncipe\" exercer pressão psíquica sobre todos nós...",
  ui_story_5085_50850702_33_dialog_content = "Seus gritos desesperados são música para os meus ouvidos. Por suas próprias ações imprudentes, você trouxe dor e sofrimento aos seus súditos—",
  ui_story_5085_50850702_34_dialog_content = "Eles não são meus súditos! Eles são meus amigos! E—",
  ui_story_5085_50850702_35_dialog_content = "Você também é um de nós!!!",
  ui_story_5085_50850702_36_dialog_content = "...",
  ui_story_5085_50850702_37_dialog_content = "Eu... sou um ator... Abençoado com as memórias do príncipe...",
  ui_story_5085_50850702_38_dialog_content = "Aham... Agora, vamos continuar nossa gloriosa performance...",
  ui_story_5085_50850702_39_dialog_content = "Viajantes de longe! Que prova vocês têm de se identificar como meus súditos mais leais?",
  ui_story_5085_50850702_40_dialog_content = "Há apenas um caminho a seguir: complete minhas missões e desperte as memórias dentro desses emblemas!",
  ui_story_5085_50850702_41_dialog_content = "Somente então concederei a você passagem.",
  ui_story_5085_50850702_42_dialog_content = "Hã?? Isso significa que você vai nos deixar entrar nas ruínas?",
  ui_story_5085_50850702_43_dialog_content = "Só precisamos completar essas \"missões\", certo?",
  ui_story_5085_50850702_44_dialog_content = "Então ainda há esperança! Enquanto conseguirmos entrar nas ruínas, temos uma chance de salvar Fleur!",
  ui_story_5085_50850702_45_dialog_content = "Ouçam minhas palavras, viajantes! As missões dos Emblemas do Cavaleiro—",
  ui_story_5085_50850702_46_dialog_content = "\"Derrote cem monstros sugadores de sangue, para que nosso reino finalmente possa dormir em paz e conforto.\"",
  ui_story_5085_50850702_47_dialog_content = "\"Monstros sugadores de sangue\"...? E-Existem realmente criaturas tão assustadoras nesta ilha?",
  ui_story_5085_50850702_48_dialog_content = "Um monstro sugador de sangue... Poderia ser aquela coisa que eu vi com PlayerName antes?",
  ui_story_5085_50850702_49_dialog_content = "A próxima é a missão do Emblema do Músico—",
  ui_story_5085_50850702_50_dialog_content = "\"Ofereça aos soldados do nosso reino uma noite de sono tranquila com a canção de ninar mais suave do mundo.\"",
  ui_story_5085_50850702_51_dialog_content = "... Uma canção de ninar?!",
  ui_story_5085_50850702_52_dialog_content = "Esse é o pior cenário possível para um ídolo de rock pesado como eu!!",
  ui_story_5085_50850702_53_dialog_content = "E finalmente, a busca pelo Emblema do Mago—",
  ui_story_5085_50850702_54_dialog_content = "\"Invoque um vento milagroso para embalar o palácio em uma brisa suave e agradável para sempre.\"",
  ui_story_5085_50850702_55_dialog_content = "...",
  ui_story_5085_50850702_56_dialog_content = "...",
  ui_story_5085_50850702_57_dialog_content = "Por que todas essas missões têm algo a ver com dormir?!?",
  ui_story_5085_50850702_58_dialog_content = "Heheheh... Parece que o príncipe tem uma insônia séria...",
  ui_story_5085_50850702_59_dialog_content = "É por isso que o príncipe deixou seu reino em primeiro lugar? Ridículo—",
  ui_story_5085_50850702_60_dialog_content = "Eu me pergunto... Como devemos criar uma brisa perpétua para \"embalar o palácio\"?",
  ui_story_5085_50850702_62_dialog_content = "Quando os três emblemas despertarem, nosso reino renascerá.",
  ui_story_5085_50850702_63_dialog_content = "Tenho confiança que... Você encontrará as respostas.",
  ui_story_5085_50850702_64_dialog_content = "Que conjunto de missões problemáticas.",
  ui_story_5085_50850702_65_dialog_content = "Estou apenas grato por termos recebido um caminho a seguir. Pelo menos sabemos o que precisamos fazer agora.",
  ui_story_5085_50850702_66_dialog_content = "O que você acha, Ryza?",
  ui_story_5085_50850702_67_dialog_content = "Vamos continuar em movimento. Tenho certeza de que a resposta se revelará em breve.",
  ui_story_5085_50850702_68_dialog_content = "Na verdade... Eu já tenho algumas ideias para completar essas missões!",
  ui_story_5085_50850800_1_dialog_content = "Uh-oh, temos mais Eclipsites!",
  ui_story_5085_50850800_2_dialog_content = "Onde devemos encontrar esses \"monstros sugadores de sangue\" para a missão do Cavaleiro?",
  ui_story_5085_50850800_3_dialog_content = "Na verdade, o Navegador e eu já tínhamos um plano para isso!",
  ui_story_5085_50850800_4_dialog_content = "É por isso que acho que a missão do Emblema do Cavaleiro não deveria ser um problema para nós!",
  ui_story_5085_50850800_5_dialog_content = "A missão do Mago provavelmente será a mais problemática... Como é que se supõe que criemos algo que possa invocar uma brisa perpétua?",
  ui_story_5085_50850800_6_dialog_content = "Na verdade, tenho algumas ideias que podem ser úteis para você, Ryza!",
  ui_story_5085_50850900_1_dialog_content = "Excelente... Graças à ajuda da Srta. Vice, parece que Ryza descobriu uma nova direção para explorar com sua alquimia.",
  ui_story_5085_50850900_2_dialog_content = "Sério? Isso é ótimo! Eu também tenho feito progressos do meu lado.",
  ui_story_5085_50850900_3_dialog_content = "Em breve, teremos dois emblemas despertados em nossa posse!",
  ui_story_5085_50850900_4_dialog_content = "E você, Klaudia? Você e Barbara parecem estar trabalhando muito bem juntos.",
  ui_story_5085_50850900_5_dialog_content = "Fizemos bastante progresso também, mas ainda estou um pouco nervoso...",
  ui_story_5085_50850902_1_dialog_content = "Desculpe a espera—",
  ui_story_5085_50850902_2_dialog_content = "Acho... Acho que conseguimos!",
  ui_story_5085_50850902_3_dialog_content = "Aposto que o príncipe não esperava que completássemos suas missões tão rapidamente!",
  ui_story_5085_50850902_4_dialog_content = "Ei—consciência das ruínas, ou quem quer que você seja—",
  ui_story_5085_50850902_5_dialog_content = "Terminamos todas as suas três missões!",
  ui_story_5085_50850902_6_dialog_content = "... Você deve primeiro me dizer como alcançou suas metas.",
  ui_story_5085_50850902_7_dialog_content = "Vamos começar.",
  ui_story_5085_50850902_8_dialog_content = "Direita!",
  ui_story_5085_50850902_9_dialog_content = "Primeiro, o Emblema do Cavaleiro!",
  ui_story_5085_50850902_10_dialog_content = "... Zarya e eu completamos aquela juntos!",
  ui_story_5085_50850902_11_dialog_content = "C-Como um guardião real de Queen Bethlehem... Estou mais do que disposto a empreender uma missão de cavaleiro!",
  ui_story_5085_50850902_12_dialog_content = "Com nossa força combinada, eliminamos cem mosquitos Eclipsite da ilha!",
  ui_story_5085_50850902_13_dialog_content = "Isso deve satisfazer o requisito da missão de matar \"cem monstros sugadores de sangue\", certo?",
  ui_story_5085_50850902_14_dialog_content = "Eu só queria que pudéssemos ter incluído o Ryza que eu espantei na noite anterior...",
  ui_story_5085_50850902_15_dialog_content = "Em seguida, o Emblema do Músico!",
  ui_story_5085_50850902_16_dialog_content = "Sim, sim, sim! Quando se trata de música, nenhum desafio é grande demais para a ídola número um, Barbara!",
  ui_story_5085_50850902_17_dialog_content = "E com o incrível apoio da Senhorita Klaudia...",
  ui_story_5085_50850902_18_dialog_content = "Nossa música já maravilhosa se tornou uma força imparável de superioridade sonora!",
  ui_story_5085_50850902_19_dialog_content = "Heheh, eu simplesmente forneci acompanhamento instrumental para a bela voz da Senhorita Barbara.",
  ui_story_5085_50850902_20_dialog_content = "O canto dela é verdadeiramente espetacular!",
  ui_story_5085_50850902_21_dialog_content = "Tudo o que fizemos foi mudar o modo de expressão; o amor no meu coração ainda queima tão quente quanto sempre!",
  ui_story_5085_50850902_22_dialog_content = "E com isso, nós demos aos soldados do reino a canção de ninar mais doce que eles já ouviram!",
  ui_story_5085_50850902_23_dialog_content = "E finalmente, o Emblema do Mago!",
  ui_story_5085_50850902_24_dialog_content = "Contemple! Esse é o poder—",
  ui_story_5085_50850902_25_dialog_content = "Da minha alquimia! Com a ajuda de todos, criamos o gerador de vento supremo!",
  ui_story_5085_50850902_26_dialog_content = "Eu forneci o design, Zarya forneceu os cubos de gelo e Ryza forneceu as peças. Depois disso, todos nós trabalhamos juntos para montá-lo.",
  ui_story_5085_50850902_27_dialog_content = "Embora de volta à Illumina, nós nos referíamos a isso como um \"ar condicionado\" ou algo do tipo...",
  ui_story_5085_50850902_28_dialog_content = "Mas o nome não é importante!",
  ui_story_5085_50850902_29_dialog_content = "Com esta máquina, conseguimos invocar um vento milagroso para \"embalar o palácio em uma brisa suave e agradável\"!",
  ui_story_5085_50850902_30_dialog_content = "Para os antigos aurorianos que já viveram aqui, um dispositivo tão avançado e conveniente teria sido ainda mais impressionante do que a magia!",
  ui_story_5085_50850902_31_dialog_content = "Entendo... Então essas são as respostas que você trouxe para mim.",
  ui_story_5085_50850902_32_dialog_content = "Mesmo assim...",
  ui_story_5085_50850902_33_dialog_content = "Antes de conceder a sua entrada, preciso ter certeza da sua lealdade.",
  ui_story_5085_50850902_34_dialog_content = "Agora você deve provar para mim que a amizade vale mais do que ouro!",
  ui_story_5085_50850902_35_dialog_content = "Depois de toda essa correria, agora você quer que provemos nossa amizade?!",
  ui_story_5085_50850902_36_dialog_content = "Talvez ele só queira que provemos a amizade entre o príncipe e os proprietários desses emblemas?",
  ui_story_5085_50850902_37_dialog_content = "Mas isso é completamente redundante!",
  ui_story_5085_50850902_38_dialog_content = "Tudo bem, ficarei feliz em provar isso para você!",
  ui_story_5085_50850902_39_dialog_content = "Hã?",
  ui_story_5085_50850902_40_dialog_content = "E isso é porque—Somos os amigos mais próximos do príncipe!",
  ui_story_5085_50850902_41_dialog_content = "Tudo o que fizemos até agora é em serviço do príncipe \"atual\". Isso é completamente verdade.",
  ui_story_5085_50850902_42_dialog_content = "E se você não acredita em mim, vou usar o calor das minhas mãos para provar isso para você!",
  ui_story_5085_50850902_43_dialog_content = "...",
  ui_story_5085_50850902_44_dialog_content = "Vamos, todos! Ajudem o Navegador a abrir o portão!",
  ui_story_5085_50850902_45_dialog_content = "Ryza... PlayerName...",
  ui_story_5085_50850902_46_dialog_content = "Não podemos nos dar ao luxo de sermos parados em um lugar como este! Vamos lá!",
  ui_story_5085_50850902_47_dialog_content = "Vou ajudar PlayerName também!",
  ui_story_5085_50850902_48_dialog_content = "Um dos nossos da Chave Rediesel está lá! Tenho o dever de trazê-lo para casa!",
  ui_story_5085_50850902_49_dialog_content = "E-Eu jurei para mim mesmo... Que nunca mais perderia para ninguém!",
  ui_story_5085_50850902_50_dialog_content = "\"Coloque suas mãos no portão e abra-o com seus corações.\"",
  ui_story_5085_50850902_51_dialog_content = "Esse calor... Essa paixão...",
  ui_story_5085_50850902_52_dialog_content = "A glória do nosso passado finalmente ressurgiu.",
  ui_story_5085_50850902_53_dialog_content = "As portas para o meu reino estão abertas para você!",
  ui_story_5085_50850902_54_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5085_50850902_55_dialog_content = "Conseguimos!",
  ui_story_5085_50851001_1_dialog_content = "Finalmente conseguimos entrar nas ruínas!",
  ui_story_5085_50851001_2_dialog_content = "Uau, é tão incrível por dentro! Aposto que este lugar parecia realmente impressionante naquela época!",
  ui_story_5085_50851001_3_dialog_content = "Devemos continuar cautelosos. O tempo corroeu grande parte do interior...",
  ui_story_5085_50851001_4_dialog_content = "Não podemos esquecer da consciência também. Não há como dizer o que ele está tramando agora.",
  ui_story_5085_50851001_5_dialog_content = "Ugh! Finalmente conseguimos abrir o portão, mas Fleur não está em lugar nenhum novamente!",
  ui_story_5085_50851001_6_dialog_content = "Olhe para lá—É aquele o trono?",
  ui_story_5085_50851001_7_dialog_content = "Tem alguém sentado nele! Talvez seja o Fleur...",
  ui_story_5085_50851001_8_dialog_content = "Ei, realmente é ele!",
  ui_story_5085_50851001_9_dialog_content = "Fleur—!",
  ui_story_5085_50851001_10_dialog_content = "...",
  ui_story_5085_50851001_11_option_content = "Mindlink—",
  ui_story_5085_50851001_12_dialog_content = "<color=#e8d9bb>Crepitar—</color>",
  ui_story_5085_50851001_13_dialog_content = "Não me lembro de quando começou, mas os Eclipsitas começaram a nos atacar todas as noites.",
  ui_story_5085_50851001_14_dialog_content = "Até hoje, ainda não sei quando ou por que eles apareceram, mas trouxeram uma dor e sofrimento incontáveis para o meu povo.",
  ui_story_5085_50851001_15_dialog_content = "Noite após noite sem dormir, assisti meus amigos e entes queridos serem tirados de mim um por um.",
  ui_story_5085_50851001_16_dialog_content = "E assim decidi deixar o reino e buscar ajuda no continente. O rei não deve ser forçado a enfrentar essa crise sozinho.",
  ui_story_5085_50851001_17_dialog_content = "Ó sábio e antigo espírito das ruínas... Por favor, lembre-se das minhas intenções.",
  ui_story_5085_50851001_18_dialog_content = "Se eu retornar vitorioso, prometa-me que cantará meus louvores. Mas se eu nunca voltar, por favor, não me lamente...",
  ui_story_5085_50851001_19_dialog_content = "Estes <color=#FFB400>três emblemas</color> simbolizam três pessoas de mais alto caráter moral.",
  ui_story_5085_50851001_20_dialog_content = "Nas mãos dos dignos, esses emblemas trarão nova vida ao nosso reino algum dia...",
  ui_story_5085_50851001_21_dialog_content = "Príncipe...",
  ui_story_5085_50851001_22_dialog_content = "Nós iremos?",
  ui_story_5085_50851001_23_dialog_content = "... Fleur ainda não recuperou a consciência, mas acho que sei por que você e seus amigos foram convocados para este mundo, Ryza...",
  ui_story_5085_50851001_24_dialog_content = "Hã?!",
  ui_story_5085_50851001_25_dialog_content = "O príncipe deixou a ilha para pedir ajuda ao continente, e confiou às ruínas sua última mensagem.",
  ui_story_5085_50851001_26_dialog_content = "Se ele falhasse em retornar, o reino deveria ser deixado nas mãos das três pessoas portadoras desses emblemas...",
  ui_story_5085_50851001_27_dialog_content = "O Cavaleiro, o Mago e o Músico...?",
  ui_story_5085_50851001_28_dialog_content = "Então isso deve significar... O príncipe nunca voltou...",
  ui_story_5085_50851001_29_dialog_content = "Isso mesmo, e nos incontáveis anos após a queda de seu reino...",
  ui_story_5085_50851001_30_dialog_content = "As ruínas têm esperado pelo retorno do príncipe, e procurado incansavelmente por três pessoas dignas para pegar esses emblemas e restaurar o reino.",
  ui_story_5085_50851001_31_dialog_content = "E como todos vocês eram dignos dos emblemas, as ruínas convocaram vocês aqui de outro mundo por engano. Se eu tivesse que adivinhar, provavelmente foi por volta do momento em que Fleur foi confundido com o príncipe e preso aqui.",
  ui_story_5085_50851001_32_dialog_content = "Então foi assim que aconteceu! Então o verdadeiro príncipe...",
  ui_story_5085_50851001_33_dialog_content = "Independentemente de ele ter voltado em segurança ou não, ele agora é apenas um sonho inatingível.",
  ui_story_5085_50851001_34_dialog_content = "Que maneira terrível de as coisas terminarem...",
  ui_story_5085_50851001_35_dialog_content = "Cuidado! Acima de nós!!",
  ui_story_5085_50851001_36_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5085_50851001_37_dialog_content = "As ruínas estão começando a tremer!",
  ui_story_5085_50851001_38_dialog_content = "Ah... Ahhhhhhh—",
  ui_story_5085_50851001_39_dialog_content = "Fleur?! Qu-Qu-Qual é o problema com você?!",
  ui_story_5085_50851001_40_dialog_content = "Ah!",
  ui_story_5085_50851001_41_dialog_content = "Temos que sair daqui! Se as ruínas estão perdendo o controle, então Fleur está—",
  ui_story_5085_50851001_42_dialog_content = "Fleur... Ele está se tornando um com a pedra e a maquinaria das ruínas!",
  ui_story_5085_50851001_43_dialog_content = "Ele está se transformando em um robô?!",
  ui_story_5085_50851001_44_dialog_content = "Hã?",
  ui_story_5085_50851001_45_dialog_content = "Então são as ruínas fazendo isso? Ou poderia ser que Fleur finalmente está resistindo ao controle deles?",
  ui_story_5085_50851001_46_dialog_content = "Não acho que essa seja nossa maior preocupação agora!",
  ui_story_5085_50851001_47_dialog_content = "Ele vai destruir todo este lugar se não o impedirmos logo!!!",
  ui_story_5085_50851001_48_dialog_content = "O reino deve renascer... Eu preciso realizar nosso sonho!",
  ui_story_5085_50851001_49_dialog_content = "Hraaaaaah—!",
  ui_story_5085_50851002_1_dialog_content = "Ele está começando a se desmoronar! Agora, Navegador!",
  ui_story_5085_50851002_2_dialog_content = "Sim!",
  ui_story_5085_50851002_3_dialog_content = "<color=#e8d9bb>Baque-</color>",
  ui_story_5085_50851002_4_dialog_content = "Fleur! Você está bem?!",
  ui_story_5085_50851002_5_dialog_content = "Meu mecha... Meu reino...",
  ui_story_5085_50851002_6_dialog_content = "Ele ainda não saiu disso... Eu vou apenas carregá-lo para fora daqui... Hmm?",
  ui_story_5085_50851002_7_dialog_content = "?!?",
  ui_story_5085_50851002_8_dialog_content = "Vocês três estão brilhando de repente...",
  ui_story_5085_50851002_9_dialog_content = "... Exatamente como os três emblemas!",
  ui_story_5085_50851002_10_dialog_content = "Entendo... O príncipe queria que nos reuníssemos aqui desde o início.",
  ui_story_5085_50851002_11_dialog_content = "E agora que sua consciência se foi... É hora dos salvadores escolhidos de seu reino também retornarem.",
  ui_story_5085_50851002_12_dialog_content = "Mas...",
  ui_story_5085_50851002_13_dialog_content = "As ruínas... E toda esta montanha! Estão todas prestes a desmoronar!",
  ui_story_5085_50851002_14_dialog_content = "Não é apenas a montanha... A ilha inteira está tremendo! O que devemos fazer...?",
  ui_story_5085_50851002_15_dialog_content = "Vá para a praia. Seu amigo está te esperando lá.",
  ui_story_5085_50851002_16_dialog_content = "Fleur? Não, espera... Você é o príncipe, não é? O que você quer dizer com \"nosso amigo\"?",
  ui_story_5085_50851002_17_dialog_content = "Ele está certo, você sabe! Pelo menos estaremos seguros dos destroços caindo na praia, então vamos nos apressar!",
  ui_story_5085_50851002_18_dialog_content = "Então parece que nossa missão final...",
  ui_story_5085_50851002_19_dialog_content = "É para escoltar todos em segurança até a praia antes de voltarmos para o nosso próprio mundo! Ainda há tempo!",
  ui_story_5085_50851002_20_dialog_content = "Certo! Vamos nos apressar!",
  ui_story_5085_50851002_21_dialog_content = "Vocês...",
  ui_story_5085_50851002_22_dialog_content = "Só espero que tenhamos a chance de dizer nossos adeus quando chegarmos lá!",
  ui_story_5085_50851100_1_dialog_content = "Ei—aqui—",
  ui_story_5085_50851100_2_dialog_content = "Sr. Corax—!",
  ui_story_5085_50851100_3_dialog_content = "(Então o amigo que ele mencionou era Corax, huh.)",
  ui_story_5085_50851100_4_dialog_content = "Todos estão seguros? O navio de resgate fará o desembarque em breve, então por favor aguente só um pouco mais.",
  ui_story_5085_50851100_5_dialog_content = "Ufa... Finalmente chegamos ao barco. Não estamos esquecendo ninguém desta vez, estamos?",
  ui_story_5085_50851100_6_dialog_content = "Não vejo Ryza em lugar nenhum... Ryza! Onde você está?!",
  ui_story_5085_50851100_7_dialog_content = "Eu... tô aqui!",
  ui_story_5085_50851100_8_dialog_content = "Desculpe se fiz alguém se preocupar.",
  ui_story_5085_50851100_9_dialog_content = "Se todos estão aqui agora, vou avisar o Sr. Corax que estamos prontos para zarpar.",
  ui_story_5085_50851100_10_dialog_content = "A ilha... No final, afundou no mar...",
  ui_story_5085_50851100_11_dialog_content = "Sim, e sem deixar um rastro de sua existência.",
  ui_story_5085_50851100_12_dialog_content = "Lá se vai meu dinheiro para manter o Colossus...",
  ui_story_5085_50851100_13_dialog_content = "Heheh, eu não teria tanta certeza! Dê uma olhada nisso, pessoal—",
  ui_story_5085_50851100_14_dialog_content = "São estes... Os fragmentos do trono do rei? É por isso que você demorou tanto para voltar, Ryza?!",
  ui_story_5085_50851100_15_dialog_content = "Sim! Mesmo que fosse perigoso, você continuou usando seus poderes para buscar a verdade... Então, naturalmente, eu também tive que ajudar à minha maneira!",
  ui_story_5085_50851100_17_dialog_content = "Ryza...",
  ui_story_5085_50851100_18_dialog_content = "Ela realmente se superou desta vez...",
  ui_story_5085_50851100_19_dialog_content = "Vamos ver o que os últimos fragmentos restantes daquelas ruínas podem nos dizer—",
  ui_story_5085_50851100_20_dialog_content = "Para Sua Alteza Real Príncipe,",
  ui_story_5085_50851100_21_dialog_content = "Os Eclipsitas se tornaram ainda mais selvagens, e o poder das ruínas começou a diminuir. Receio que nosso reino insular não resistirá por muito mais tempo.",
  ui_story_5085_50851100_22_dialog_content = "E assim, decidimos seguir seus nobres passos e liderar nosso povo até o continente em busca de um novo lar.",
  ui_story_5085_50851100_23_dialog_content = "Podemos não ser capazes de cantar seus louvores em seu retorno triunfante...",
  ui_story_5085_50851100_24_dialog_content = "Mas tenha certeza de que seu povo não foi derrotado. Eles simplesmente escolheram começar de novo em uma terra estrangeira.",
  ui_story_5085_50851100_25_dialog_content = "May cruzamos caminhos e nos reunimos novamente em um continente brilhante e próspero.",
  ui_story_5085_50851100_26_dialog_content = "Então o reino nunca foi exterminado em primeiro lugar!",
  ui_story_5085_50851100_27_dialog_content = "Eles viajaram para o continente de Astra e encontraram novas vidas lá!",
  ui_story_5085_50851100_28_dialog_content = "Mesmo que o príncipe nunca tenha retornado de sua aventura, suas ações pavimentaram o caminho para a sobrevivência de seu povo...",
  ui_story_5085_50851100_29_dialog_content = "Isso não só o torna um príncipe digno, mas também um aventureiro corajoso!",
  ui_story_5085_50851100_30_dialog_content = "Se os descendentes deles soubessem de tudo isso... Eles tentariam se reunir uns com os outros no continente?",
  ui_story_5085_50851100_32_dialog_content = "Não importa quanto tempo passe, seus corações sempre estarão unidos. Na verdade, tenho certeza de que eles já se reencontraram em algum lugar.",
  ui_story_5085_50851100_33_dialog_content = "Também acho! Eu posso sentir o amor ardente que une seus corações!",
  ui_story_5085_50851100_34_dialog_content = "Pode não ser o final perfeito para a história deles...",
  ui_story_5085_50851100_35_dialog_content = "Mas ainda é bom... E isso deve ser mais do que suficiente.",
  ui_story_5085_50851100_36_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5085_50851100_37_dialog_content = "...",
  ui_story_5085_50851100_38_dialog_content = "Ah... Parece que é hora de nos despedirmos agora.",
  ui_story_5085_50851100_39_dialog_content = "Se tivermos a chance de nos encontrar novamente, adoraria ouvir tudo sobre suas aventuras, PlayerName...",
  ui_story_5085_50851100_40_dialog_content = "É uma pena que eu não consiga nem usar a alquimia para fazer presentes de despedida para todos, mas...",
  ui_story_5085_50851100_41_dialog_content = "Sempre valorizarei nossa aventura de hoje mais do que qualquer outro tesouro!",
  ui_story_5085_50851100_42_dialog_content = "E-Eu também! Foi um prazer conhecer todos aqui! E Senhorita Barbara, eu adoraria mais do que tudo assistir a um de seus shows algum dia!",
  ui_story_5085_50851100_43_dialog_content = "Oh? Então vou garantir que você receba o melhor tratamento VIP imaginável!",
  ui_story_5085_50851100_44_dialog_content = "Mesmo que nosso tempo juntos tenha sido curto... Eu nunca esquecerei nenhum de vocês.",
  ui_story_5085_50851100_45_dialog_content = "Zarya! Vamos dar nosso melhor e continuar crescendo!",
  ui_story_5085_50851100_46_dialog_content = "Eu-Eu não vou esquecer também, mas... Mas eu não vou perder para você também, Patty!",
  ui_story_5085_50851100_47_dialog_content = "Sei que é hora de seguirmos caminhos separados, mas simplesmente não consigo dizer isso em voz alta...",
  ui_story_5085_50851100_48_dialog_content = "Não fique tão triste, PlayerName! Tenho certeza de que nos encontraremos novamente algum dia!",
  ui_story_5085_50851100_49_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5085_50851100_50_dialog_content = "Hum...",
  ui_story_5085_50851100_51_dialog_content = "A-Ainda estamos aqui?!",
  ui_story_5085_50851100_52_dialog_content = "P-Perdoe a interrupção, mas acho que posso explicar!",
  ui_story_5085_50851100_53_dialog_content = "Fleur? Espere... Você ainda é o príncipe, não é?",
  ui_story_5085_50851100_54_dialog_content = "Não, tenho certeza de que ainda estou Fleur.",
  ui_story_5085_50851100_55_dialog_content = "\"Certeza justa\"?!",
  ui_story_5085_50851100_56_dialog_content = "Isso mesmo, embora eu tenha uma mensagem para todos do príncipe...",
  ui_story_5085_50851100_57_dialog_content = "Graças aos seus esforços, ele finalmente aprendeu que seu povo precioso conseguiu sair com segurança da ilha e começou novas vidas no continente de Astra.",
  ui_story_5085_50851100_58_dialog_content = "Ele também pediu desculpas sinceramente por causar tantos problemas para todos.",
  ui_story_5085_50851100_59_dialog_content = "Então, como um sinal de boa vontade, ele usou o último poder restante das ruínas...",
  ui_story_5085_50851100_60_dialog_content = "Para manter os três de vocês em nosso mundo por mais um pouco!",
  ui_story_5085_50851100_61_dialog_content = "Infelizmente, as ruínas não tinham muita energia restante nelas, e logo o efeito vai desaparecer.",
  ui_story_5085_50851100_62_dialog_content = "Mas, pelo menos, você poderá desfrutar de uma bela aventura de verão aqui no Astra!",
  ui_story_5085_50851100_63_dialog_content = "Hã?!",
  ui_story_5085_50851100_64_dialog_content = "Isso é ótimo e tudo mais... Mas você não acha que ele deveria estar se desculpando com você acima de tudo?",
  ui_story_5085_50851100_65_dialog_content = "Ah, não precisa se preocupar com isso. Ele já me transmitiu o conhecimento daquele mecha!",
  ui_story_5085_50851100_66_dialog_content = "Assim que chegarmos em casa, conseguirei fazer algo verdadeiramente incrível.",
  ui_story_5085_50851100_67_dialog_content = "(Espere, isso significa que ele realmente ficou chateado quando destruímos isso mais cedo!)",
  ui_story_5085_50851100_68_dialog_content = "Enfim... Acho que estamos perdendo o ponto aqui...",
  ui_story_5085_50851100_69_dialog_content = "Então... Isso significa que eu posso ficar no seu mundo um pouco mais?!",
  ui_story_5085_50851100_70_dialog_content = "Nesse caso, quero ver tudo o que este mundo tem a oferecer! A Colossus, o Deserto Rediesel, Lumopolis... Você pode nos mostrar tudo isso e mais, certo Navegador?!",
  ui_story_5085_50851100_71_dialog_content = "Claro! Vocês são nossos amigos próximos agora, bem como as pessoas que salvaram nossas vidas anteriormente.",
  ui_story_5085_50851100_72_dialog_content = "Como o Navegador da Colossus, seria uma honra receber os três de vocês a bordo!",
  ui_story_5085_50851100_73_dialog_content = "Uau, muito obrigado! Mal posso esperar para embarcar em todos os tipos de aventuras no seu mundo!",
  ui_story_5085_50851100_74_dialog_content = "Vamos nos divertir o máximo que pudermos antes que seja realmente hora de dizer adeus!",
  ui_story_5085_50851100_76_dialog_content = "Estou contando com você para me mostrar este mundo, Navegador! Tudo bem, vamos lá!",
  ui_story_5085_50851100_77_dialog_content = "Ryza, Navegador... May Posso me juntar a você também?",
  ui_story_5085_50851100_78_dialog_content = "Não esqueçam de mim!",
  ui_story_5085_50851100_79_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_5085_50851100_80_dialog_content = "<color=#e8d9bb>A ilha repousa silenciosamente no fundo do mar, junto com as evidências de sua antiga glória. Agora, uma nova aventura de verão está prestes a começar.</color>",
  ui_story_5085_50851100_81_dialog_content = "Próxima parada: Astra! Navegar a todo vapor!"
}
return config
